CREATE OR REPLACE FUNCTION finance_private.coach_self_approval_context(pid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare po public.finance_purchase_orders; f public.finance_po_approvals; paired uuid;
begin
 if auth.uid() is null or not coalesce(finance_private.role() in ('mentor')
   and public.team_has_any_position(array['lead_coach_1','lead_coach_2']),false) then
  return jsonb_build_object('eligible',false,'allowed',false,'reason','');
 end if;
 select * into po from public.finance_purchase_orders where id=pid and requester_id=auth.uid();
 if not found or not finance_private.visible(pid) then
  return jsonb_build_object('eligible',false,'allowed',false,'reason','');
 end if;
 if po.status<>'awaiting_approval' or exists(select 1 from public.finance_po_approvals a
   where a.po_id=pid and a.revision=po.revision and (a.action='changes_requested' or a.slot='po_approver' or a.actor_id=auth.uid())) then
  return jsonb_build_object('eligible',true,'allowed',false,'reason','A different Finance Lead must approve the Finance step.');
 end if;
 select * into f from public.finance_po_approvals where po_id=pid and revision=po.revision
   and slot='finance_approver' and action='approved';
 if found then
  if f.actor_id=auth.uid() or not (
    exists(select 1 from finance_private.history h where h.po_id=pid and h.revision=po.revision and h.action='approve'
      and h.actor_id=f.actor_id and h.details->>'slot'=f.slot and h.details->>'approval_id'=f.id::text
      and h.details->>'approval_authority'='assigned_finance_lead')
    or (f.override_reason='' and not exists(select 1 from finance_private.history h
      where h.po_id=pid and h.revision=po.revision and h.details->>'approval_id'=f.id::text)
      and exists(select 1 from public.profiles pr join public.team_member_positions mp on mp.user_id=pr.id
        join public.team_positions pos on pos.key=mp.position_key and pos.active
        where pr.id=f.actor_id and pr.active and pr.role::text in ('student','lead','admin_lead','mentor')
        and mp.revoked_at is null and mp.position_key='finance_lead'))
  ) then
   return jsonb_build_object('eligible',true,'allowed',false,'reason',
    'This revision has an earlier Finance override or unverified Finance assignment. Edit and resubmit before using your own Coach approval; a different assigned Finance Lead must approve the new revision.');
  end if;
  paired:=f.id;
 end if;
 return jsonb_build_object('eligible',true,'allowed',true,'reason','Approve only your Coach step. A different assigned Finance Lead must approve Finance.','paired_finance_approval_id',paired);
end $function$

CREATE OR REPLACE FUNCTION finance_private.mutate_v1(action text, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare po public.finance_purchase_orders; previous jsonb; pid uuid; slot text:=p->>'slot'; reason text:=trim(coalesce(p->>'reason','')); override_note text:=trim(coalesce(p->>'override_reason','')); caps boolean; coach_self boolean:=false; self_context jsonb; marked_self boolean:=false; approval_id uuid; authority text; paired uuid;
begin
 if finance_private.role() is null then raise exception 'Active team account required' using errcode='42501'; end if;
 if length(reason)>2000 or length(override_note)>2000 then raise exception 'Explanations must be at most 2000 characters'; end if;
 if action='assignment' then
 if p->>'capability' is null or p->>'capability' not in ('school_submitter','finance_admin') then raise exception 'Manage Lead Coach and Finance Lead positions in Team Hub'; end if;
 if not finance_private.admin() then raise exception 'Finance administration required' using errcode='42501'; end if;
 if not exists(select 1 from public.profiles where id=(p->>'user_id')::uuid and active and role::text in ('student','lead','admin_lead','mentor')) then raise exception 'Choose an active student or leadership account'; end if;
 if reason='' then raise exception 'Assignment explanation required'; end if;
 insert into public.finance_assignments(user_id,capability,active,assigned_by) values((p->>'user_id')::uuid,p->>'capability',(p->>'active')::boolean,auth.uid())
 on conflict(user_id,capability) do update set active=excluded.active,assigned_by=auth.uid(),assigned_at=clock_timestamp() returning id into pid;
 insert into finance_private.history(action,actor_id,details) values('assignment',auth.uid(),jsonb_build_object('assignment_id',pid,'user_id',p->>'user_id','capability',p->>'capability','active',p->'active','reason',reason));return pid;
 end if;
 if action='create' then
 if not finance_private.creator() then raise exception 'Registered student or leadership access required' using errcode='42501'; end if;
 if not exists(select 1 from public.areas where id=(p->>'area_id')::uuid and active) then raise exception 'Choose an active team area'; end if;
 insert into public.finance_purchase_orders(requester_id,area_id,sheet_url,vendor,amount,purpose,notes,needed_by)
 values(auth.uid(),(p->>'area_id')::uuid,trim(p->>'sheet_url'),trim(p->>'vendor'),(p->>'amount')::numeric,trim(p->>'purpose'),coalesce(p->>'notes',''),nullif(p->>'needed_by','')::date) returning * into po;
 insert into finance_private.history(po_id,revision,action,actor_id,details) values(po.id,0,'created',auth.uid(),to_jsonb(po)); return po.id;
 end if;
 pid:=(p->>'id')::uuid;
 if not finance_private.visible(pid) then raise exception 'Purchase order unavailable' using errcode='42501'; end if;
 select * into po from public.finance_purchase_orders where id=pid for update;
 previous:=to_jsonb(po);
 if po.version is distinct from (p->>'version')::integer then raise exception 'This PO changed. Refresh before acting.'; end if;
 if action in ('edit','submit','cancel') then
 if po.requester_id<>auth.uid() and not finance_private.admin() then raise exception 'Requester or Finance administrator required' using errcode='42501'; end if;
 if po.status in ('submitted_to_school','cancelled') then raise exception 'This PO is locked'; end if;
 if action='edit' then
 if not exists(select 1 from public.areas where id=(p->>'area_id')::uuid and active) then raise exception 'Choose an active team area'; end if;
 update public.finance_purchase_orders set area_id=(p->>'area_id')::uuid,sheet_url=trim(p->>'sheet_url'),vendor=trim(p->>'vendor'),amount=(p->>'amount')::numeric,
 purpose=trim(p->>'purpose'),notes=coalesce(p->>'notes',''),needed_by=nullif(p->>'needed_by','')::date,status='draft' where id=pid;
 elsif action='submit' then
 if po.status not in ('draft','changes_requested') then raise exception 'Only drafts or requested changes can be submitted'; end if;
 update public.finance_purchase_orders set revision=revision+1,status='awaiting_approval',submitted_at=clock_timestamp() where id=pid returning * into po;
 insert into public.finance_po_revisions(po_id,revision,metadata,submitted_by) values(pid,po.revision,to_jsonb(po),auth.uid());
 else
 if reason='' then raise exception 'Cancellation explanation required'; end if;
 update public.finance_purchase_orders set status='cancelled' where id=pid;
 end if;
 elsif action in ('approve','request_changes') then
 if po.status<>'awaiting_approval' then raise exception 'PO is not awaiting approval'; end if;
 if exists(select 1 from public.finance_po_approvals a where a.po_id=pid and a.revision=po.revision and a.action='changes_requested') then raise exception 'This revision requires resubmission'; end if;
 if slot is null or slot not in ('finance_approver','po_approver') then raise exception 'Choose an approval slot'; end if;
 -- Emergency exception: an active mentor may replace ONE position-based
 -- approver (including on their own PO) only with an explicit override reason.
 -- The same actor can NEVER approve both slots, including through overrides.
 caps:=finance_private.cap(slot);
 coach_self:=action='approve' and slot='po_approver' and po.requester_id=auth.uid()
   and finance_private.role() in ('mentor') and caps;
 marked_self:=exists(select 1 from public.finance_po_approvals c join finance_private.history h
 on h.po_id=c.po_id and h.revision=c.revision and h.actor_id=c.actor_id and h.action='approve'
 and h.details->>'approval_id'=c.id::text and h.details->>'slot'=c.slot
 and h.details->>'approval_authority'='assigned_lead_coach_self'
 where c.po_id=pid and c.revision=po.revision and c.slot='po_approver' and c.action='approved' and c.actor_id=po.requester_id);
 if coach_self then
  self_context:=finance_private.coach_self_approval_context(pid);
  if not coalesce((self_context->>'allowed')::boolean,false) then
   raise exception '%',self_context->>'reason' using errcode='42501';
  end if;
  paired:=nullif(self_context->>'paired_finance_approval_id','')::uuid;
 end if;
 if action='approve' and slot='finance_approver' and marked_self and
   (not caps or po.requester_id=auth.uid()) then
  raise exception 'A different assigned Finance Lead must approve the Finance step' using errcode='42501';
 end if;
 if not coach_self and (not caps or po.requester_id=auth.uid()) and not (finance_private.role() in ('mentor') and override_note<>'') then raise exception 'Configured approver required; mentors must give an explicit override reason' using errcode='42501'; end if;
 if override_note<>'' and finance_private.role() not in ('mentor') then raise exception 'Only mentors can override' using errcode='42501'; end if;
 if action='request_changes' and reason='' then raise exception 'Explain the requested changes'; end if;
 if action='approve' and exists(select 1 from public.finance_po_approvals a where a.po_id=pid and a.revision=po.revision and a.action='approved' and a.actor_id=auth.uid()) then raise exception 'Two distinct people must approve each revision'; end if;
 insert into public.finance_po_approvals(po_id,revision,slot,action,actor_id,explanation,override_reason)
 values(pid,po.revision,slot,case when action='approve' then 'approved' else 'changes_requested' end,auth.uid(),reason,override_note) returning id into approval_id;
 authority:=case when coach_self then 'assigned_lead_coach_self' when slot='finance_approver' and caps and po.requester_id<>auth.uid() then 'assigned_finance_lead' when slot='po_approver' and caps and po.requester_id<>auth.uid() then 'assigned_lead_coach' else 'mentor_admin_override' end;
 update public.finance_purchase_orders set status=case when action='request_changes' then 'changes_requested'
 when finance_private.revision_approved(pid,po.revision)
 -- The new record-bound authority history is inserted below in the SAME transaction.
 -- Only the already-validated normal self-Coach pair / different Finance vote may
 -- bridge that insertion order; a failed history insert rolls back the approval.
 or (action='approve' and ((coach_self and paired is not null) or (marked_self and slot='finance_approver' and authority='assigned_finance_lead'))
   and not exists(select 1 from public.finance_po_approvals qa where qa.po_id=pid and qa.revision=po.revision and qa.action='changes_requested')
   and (select count(distinct qa.slot)=2 and count(distinct qa.actor_id)=2 from public.finance_po_approvals qa where qa.po_id=pid and qa.revision=po.revision and qa.action='approved')) then 'approved'  else 'awaiting_approval' end where id=pid;
 elsif action='school_submit' then
 if not (finance_private.cap('school_submitter') or finance_private.role() in ('mentor')) then raise exception 'School submission capability required' using errcode='42501'; end if;
 if po.status<>'approved' or not finance_private.revision_approved(pid,po.revision) then raise exception 'Both current-revision approvals are required'; end if;
 update public.finance_purchase_orders set status='submitted_to_school',school_submitted_by=auth.uid(),school_submitted_at=clock_timestamp(),school_reference=trim(coalesce(p->>'reference','')),school_note=trim(coalesce(p->>'note','')) where id=pid;
 else raise exception 'Unknown Finance action'; end if;
 update public.finance_purchase_orders set version=version+1,updated_at=clock_timestamp() where id=pid;
 insert into finance_private.history(po_id,revision,action,actor_id,details)
 select pid,revision,action,auth.uid(),jsonb_build_object('reason',reason,'slot',slot,'override_reason',override_note,'self_approval_override',action='approve' and po.requester_id=auth.uid() and not coach_self,
 'approval_id',approval_id,'approval_authority',authority,'paired_finance_approval_id',paired,'before',previous,'after',to_jsonb(n)) from public.finance_purchase_orders n where id=pid;
 return pid;
end $function$

CREATE OR REPLACE FUNCTION notifications_private.enqueue(h finance_private.history)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n jsonb:=h.details->'after'; kind text; positions text[]:='{}'; recipients uuid[]:='{}'; approvers uuid[]:='{}'; r uuid; body jsonb; requester uuid; explicit_count integer;
begin
 if h.po_id is null or n is null then return; end if;
 requester:=(n->>'requester_id')::uuid;
 if h.action='submit' then kind:='approval_needed';positions:=array['lead_coach_1','lead_coach_2','finance_lead'];
 elsif h.action='request_changes' then kind:='changes_requested';recipients:=array[requester];
 elsif h.action='school_submit' then
  kind:='submitted_to_school';
  select array[requester]||coalesce(array_agg(distinct a.actor_id),'{}') into recipients from public.finance_po_approvals a where a.po_id=h.po_id and a.revision=h.revision and a.action='approved';
 elsif h.action='cancel' then
  kind:='cancelled';recipients:=array[requester];
  if h.revision>0 then
   positions:=array['lead_coach_1','lead_coach_2','finance_lead'];
   select recipients||coalesce(array_agg(distinct a.actor_id),'{}') into recipients from public.finance_po_approvals a where a.po_id=h.po_id and a.revision=h.revision;
  end if;
 elsif h.action='approve' and n->>'status'='approved' then
  kind:='ready_for_school';
  select coalesce(array_agg(distinct p.id),'{}'),count(*) into recipients,explicit_count
  from public.profiles p left join public.finance_assignments a on p.id=a.user_id and a.capability='school_submitter' and a.active
  where p.active and p.role::text in ('student','lead','admin_lead','mentor') and (p.role::text='admin_lead' or a.id is not null);
  if explicit_count=0 then
   select coalesce(array_agg(id),'{}') into recipients from public.profiles where active and role::text in ('mentor');
   -- Existing Finance authorization allows these roles, but avoid broad blasts.
   if cardinality(recipients)>5 then recipients:='{}';raise warning 'Finance notification requires explicit school submitter assignments';end if;
  end if;
 elsif h.action='approve' and n->>'status'='awaiting_approval' then
  kind:='approval_recorded';recipients:=array[requester];
  if h.details->>'slot'='po_approver' then positions:=array['finance_lead'];
  elsif h.details->>'slot'='finance_approver' then positions:=array['lead_coach_1','lead_coach_2'];
  else return;end if;
 else return;end if;
 if h.action='approve' and n->>'status'='approved' then recipients:=recipients||array[requester];end if;
 if cardinality(positions)>0 then
  select coalesce(array_agg(distinct mp.user_id),'{}') into approvers
  from public.team_member_positions mp join public.team_positions pos on pos.key=mp.position_key and pos.active
  join public.profiles p on p.id=mp.user_id and p.active and p.role::text in ('student','lead','admin_lead','mentor')
  where mp.revoked_at is null and mp.position_key=any(positions) and mp.user_id<>requester
  -- A person who already approved cannot fill the other slot.
  and (h.action='cancel' or not exists(select 1 from public.finance_po_approvals a where a.po_id=h.po_id and a.revision=h.revision and a.action='approved' and a.actor_id=mp.user_id));
  recipients:=recipients||approvers;
 end if;
 body:=jsonb_build_object('po_number',n->'po_number','vendor',n->>'vendor','amount',n->'amount',
 'revision',h.revision,'action',h.action,'slot',h.details->>'slot','resubmitted',h.action='submit' and h.revision>1,'purpose',left(n->>'purpose',350),
 'requester',(select display_name from public.profiles where id=requester),
 'area',(select name from public.areas where id=(n->>'area_id')::uuid),
 'actor',(select display_name from public.profiles where id=h.actor_id),
 'explanation',h.details->>'reason','submitted_at',n->>'school_submitted_at','reference',n->>'school_reference');
 for r in select distinct unnest(recipients) loop
  if r<>h.actor_id and exists(select 1 from public.profiles where id=r and active and role::text in ('student','lead','admin_lead','mentor')) then
   insert into public.team_notifications(source_event_id,event,recipient_id,entity_id,payload)
   values(h.id,kind,r,h.po_id,body) on conflict do nothing;
  end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION outreach_private.can_edit_record(entity text, ident uuid, actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not exists(select 1 from public.profiles where id=actor and active and role::text in ('mentor','student','lead','admin_lead')) then return false;end if;
 if entity='organization' then return exists(select 1 from outreach_private.organizations o where o.id=ident and
  (outreach_private.manager(actor) or (o.active and o.created_by=actor)));
 elsif entity='contact' then return exists(select 1 from outreach_private.contacts c where c.id=ident and
  (outreach_private.manager(actor) or c.created_by=actor) and outreach_private.can_add_contact(c.organization_id,actor));
 elsif entity='engagement' then return outreach_private.can_work_engagement(ident,actor);
 elsif entity='conversation' then return exists(select 1 from outreach_private.conversations c where c.id=ident and
  (outreach_private.manager(actor) or c.created_by=actor) and outreach_private.can_work_engagement(c.engagement_id,actor));
 elsif entity='pledge' then return outreach_private.manager(actor) and exists(select 1 from outreach_private.pledges p where p.id=ident and outreach_private.can_work_engagement(p.engagement_id,actor));
 elsif entity='recognition' then return outreach_private.manager(actor) and exists(select 1 from outreach_private.recognition r where r.id=ident and outreach_private.can_work_engagement(r.engagement_id,actor));
 end if;
 return false;
end $function$

CREATE OR REPLACE FUNCTION outreach_private.require_participant(expected_actor uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();
begin
 if actor is null or (expected_actor is not null and expected_actor<>actor) or not exists(
  select 1 from public.profiles where id=actor and active and role::text in ('mentor','student','lead','admin_lead'))
 then raise exception 'Active outreach account required' using errcode='42501';end if;
 return actor;
end $function$

CREATE OR REPLACE FUNCTION outreach_private.save(entity text, p jsonb, request_id uuid, expected_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; ident uuid; table_name text; previous jsonb; after_value jsonb; result jsonb; receipt outreach_private.requests; input_payload jsonb:=p; manager boolean;
 org uuid; eng uuid; sid uuid; owner uuid; contact uuid; pledge uuid; current_version integer;
begin
 actor:=outreach_private.require_participant(expected_actor);manager:=outreach_private.manager(actor);
 if not manager and entity in ('pledge','recognition') then raise exception 'Mentor oversight required' using errcode='42501';end if;
 if expected_actor is null or request_id is null or p is null or jsonb_typeof(p)<>'object' then raise exception 'Actor, request and object payload required' using errcode='22023';end if;
 table_name:=case entity when 'prospect' then 'organizations' when 'organization' then 'organizations' when 'contact' then 'contacts' when 'engagement' then 'engagements' when 'conversation' then 'conversations' when 'pledge' then 'pledges' when 'recognition' then 'recognition' end;
 if table_name is null then raise exception 'Unknown Outreach entity' using errcode='22023';end if;
 ident:=nullif(p->>'id','')::uuid;current_version:=(p->>'version')::integer;
 if ident is null or current_version is null or current_version<0 then raise exception 'Record ID and version required' using errcode='22023';end if;
 -- Small-team V1: one short transaction lock avoids cross-entity races. No I/O
 -- or notification dispatch is performed while holding it.
 perform pg_advisory_xact_lock(4418,80);
 actor:=outreach_private.require_participant(expected_actor);manager:=outreach_private.manager(actor);
 if not manager and entity in ('pledge','recognition') then raise exception 'Mentor oversight required' using errcode='42501';end if;
 select * into receipt from outreach_private.requests r where r.actor_id=actor and r.request_id=save.request_id;
 if found then
  if receipt.operation='canceled' then raise exception 'Request was canceled before application' using errcode='22023';end if;
  if receipt.operation<>entity or receipt.payload<>input_payload then raise exception 'Request ID already used for different data' using errcode='22023';end if;
  perform outreach_private.require_receipt(receipt,actor);
  return receipt.result;
 end if;
 execute format('select to_jsonb(t) from outreach_private.%I t where id=$1 for update',table_name) into previous using ident;
 actor:=outreach_private.require_participant(expected_actor);manager:=outreach_private.manager(actor);
 if not manager and entity in ('pledge','recognition') then raise exception 'Mentor oversight required' using errcode='42501';end if;
 if (previous is null and current_version<>0) or (previous is not null and current_version<>(previous->>'version')::integer) then
  raise exception 'Changed by another teammate. Refresh before saving.' using errcode='40001';end if;
 if entity='prospect' and previous is not null then raise exception 'Prospect identity already exists' using errcode='40001';end if;
 if previous is not null and entity='conversation' then raise exception 'Conversation entries are append-only; add a correction note' using errcode='22023';end if;
 if previous is not null then
  if (entity='contact' and previous->>'organization_id' is distinct from p->>'organization_id') or
     (entity='engagement' and (previous->>'organization_id' is distinct from p->>'organization_id' or previous->>'season_id' is distinct from p->>'season_id')) or
     (entity in ('pledge','recognition') and previous->>'engagement_id' is distinct from p->>'engagement_id') then
   raise exception 'Organization, engagement and season links cannot be moved' using errcode='22023';end if;
 end if;
 if entity='prospect' then org:=ident;sid:=(p->>'season_id')::uuid;eng:=nullif(p->>'engagement_id','')::uuid;
  if eng is null then raise exception 'New engagement ID required' using errcode='22023';end if;
 elsif entity='contact' then org:=(p->>'organization_id')::uuid;
 elsif entity='engagement' then org:=(p->>'organization_id')::uuid;sid:=(p->>'season_id')::uuid;
 elsif entity in ('conversation','pledge','recognition') then
  eng:=(p->>'engagement_id')::uuid;
  select e.organization_id,e.season_id into org,sid from outreach_private.engagements e where e.id=eng for update;
  if not found then raise exception 'Engagement unavailable' using errcode='22023';end if;
 end if;
 if entity not in ('organization','prospect') then
  perform 1 from outreach_private.organizations where id=org and active for share;
  if not found then raise exception 'Active organization required' using errcode='22023';end if;
 end if;
 if entity in ('prospect','engagement','conversation','pledge','recognition') then
  perform 1 from public.finance_seasons where id=sid and status<>'closed' for share;
  if not found then raise exception 'Open Finance season required' using errcode='22023';end if;
 end if;
 if entity in ('prospect','engagement','recognition') then
  owner:=nullif(p->>'owner_id','')::uuid;
  if entity='prospect' or (entity='engagement' and not manager and previous is null) then
   if owner is not null and owner<>actor then raise exception 'Only mentors can assign outreach' using errcode='42501';end if;owner:=actor;
  elsif entity='engagement' and not manager then
   if p ? 'owner_id' and owner is distinct from (previous->>'owner_id')::uuid then raise exception 'Only mentors can assign outreach' using errcode='42501';end if;owner:=(previous->>'owner_id')::uuid;
  end if;
  -- Preserving an old assignment does not grant that owner current eligibility.
  -- A still-active creator can edit without a mentor-only cleanup dependency.
  if owner is not null and (entity<>'engagement' or previous is null or owner is distinct from (previous->>'owner_id')::uuid) then
   perform 1 from public.profiles where id=owner and active and role::text in ('mentor','student','lead','admin_lead') for share;
   if not found then raise exception 'Choose an active eligible owner' using errcode='22023';end if;
  end if;
 end if;
 if entity='conversation' then
  contact:=nullif(p->>'contact_id','')::uuid;
  if contact is not null then
   perform 1 from outreach_private.contacts where id=contact and organization_id=org and active for share;
   if not found then raise exception 'Choose an active contact from this organization' using errcode='22023';end if;
  end if;
 elsif entity='recognition' then
  pledge:=nullif(p->>'pledge_id','')::uuid;
  if pledge is not null then
   perform 1 from outreach_private.pledges where id=pledge and engagement_id=eng for share;
   if not found then raise exception 'Choose a pledge from this engagement' using errcode='22023';end if;
  end if;
 elsif entity='pledge' and previous is not null and previous->>'kind' is distinct from p->>'kind' and exists(select 1 from outreach_private.income_links where pledge_id=ident) then
  raise exception 'A Finance-linked pledge must remain cash' using errcode='22023';
 end if;
 -- Recheck live authority after every potentially blocking relationship lock.
 actor:=outreach_private.require_participant(expected_actor);manager:=outreach_private.manager(actor);
 if not manager and entity in ('pledge','recognition') then raise exception 'Mentor oversight required' using errcode='42501';end if;
 if p ? 'created_by' and nullif(p->>'created_by','')::uuid is distinct from coalesce((previous->>'created_by')::uuid,actor) then
  raise exception 'Record authorship cannot be changed' using errcode='42501';end if;
 if entity='conversation' and ((p ? 'author_id' and nullif(p->>'author_id','')::uuid is distinct from actor) or (p ? 'sender_id' and nullif(p->>'sender_id','')::uuid is distinct from actor)) then
  raise exception 'Conversation author is the current account' using errcode='42501';end if;
 if not manager then
  if entity='engagement' and owner is distinct from (case when previous is null then actor else (previous->>'owner_id')::uuid end) then
   raise exception 'Only mentors can assign outreach' using errcode='42501';end if;
  if previous is not null and not outreach_private.can_edit_record(entity,ident,actor) then raise exception 'This record is not owned or assigned to you' using errcode='42501';end if;
  if entity='contact' and not outreach_private.can_add_contact(org,actor) then raise exception 'This sponsor is not owned or assigned to you' using errcode='42501';end if;
  if entity='engagement' and previous is null and not exists(select 1 from outreach_private.organizations where id=org and created_by=actor) then
   raise exception 'Only mentors can assign an existing sponsor prospect' using errcode='42501';end if;
  if entity='conversation' and not outreach_private.can_work_engagement(eng,actor) then raise exception 'This prospect is not owned or assigned to you' using errcode='42501';end if;
  if entity='engagement' and p->>'stage'='committed' and previous->>'stage' is distinct from 'committed' then raise exception 'Only mentors can mark a commitment' using errcode='42501';end if;
  if entity in ('organization','contact') and p ? 'active' and (p->>'active')::boolean is distinct from coalesce((previous->>'active')::boolean,true) then raise exception 'Only mentors can archive contacts or sponsors' using errcode='42501';end if;
  -- A redacted field is never a write: preserve the stored mentor notes/flags.
  p:=jsonb_set(p,'{notes}',coalesce(previous->'notes','""'::jsonb));
  if entity in ('organization','contact') then p:=jsonb_set(p,'{active}',coalesce(previous->'active','true'::jsonb));end if;
 end if;
 if entity='prospect' then
  insert into outreach_private.organizations(id,kind,name,website,notes,created_by)
  values(ident,p->>'kind',trim(p->>'name'),trim(coalesce(p->>'website','')),'',actor);
  insert into outreach_private.engagements(id,organization_id,season_id,stage,owner_id,next_follow_up_on,notes,created_by)
  values(eng,ident,sid,'prospect',actor,nullif(p->>'next_follow_up_on','')::date,'',actor);
  insert into outreach_private.history(entity,entity_id,actor_id,request_id,action,before_data,after_data)
  select 'engagement',eng,actor,save.request_id,'created',null,to_jsonb(e) from outreach_private.engagements e where e.id=eng;
  result:=jsonb_build_object('id',ident,'version',1);
 elsif entity='organization' then
  insert into outreach_private.organizations(id,kind,name,website,notes,active,created_by)
  values(ident,p->>'kind',trim(p->>'name'),trim(coalesce(p->>'website','')),coalesce(p->>'notes',''),coalesce((p->>'active')::boolean,true),actor)
  on conflict(id) do update set kind=excluded.kind,name=excluded.name,website=excluded.website,notes=excluded.notes,active=excluded.active,version=organizations.version+1,updated_at=clock_timestamp()
  returning jsonb_build_object('id',id,'version',version) into result;
 elsif entity='contact' then
  insert into outreach_private.contacts(id,organization_id,name,title,email,phone,notes,active,created_by)
  values(ident,org,trim(p->>'name'),coalesce(p->>'title',''),trim(coalesce(p->>'email','')),coalesce(p->>'phone',''),coalesce(p->>'notes',''),coalesce((p->>'active')::boolean,true),actor)
  on conflict(id) do update set name=excluded.name,title=excluded.title,email=excluded.email,phone=excluded.phone,notes=excluded.notes,active=excluded.active,version=contacts.version+1,updated_at=clock_timestamp()
  returning jsonb_build_object('id',id,'version',version) into result;
 elsif entity='engagement' then
  insert into outreach_private.engagements(id,organization_id,season_id,stage,owner_id,next_follow_up_on,notes,created_by)
  values(ident,org,sid,p->>'stage',owner,nullif(p->>'next_follow_up_on','')::date,coalesce(p->>'notes',''),actor)
  on conflict(id) do update set stage=excluded.stage,owner_id=excluded.owner_id,next_follow_up_on=excluded.next_follow_up_on,notes=excluded.notes,version=engagements.version+1,updated_at=clock_timestamp()
  returning jsonb_build_object('id',id,'version',version) into result;
 elsif entity='conversation' then
  insert into outreach_private.conversations(id,engagement_id,contact_id,occurred_on,channel,summary,created_by)
  values(ident,eng,contact,(p->>'occurred_on')::date,p->>'channel',trim(p->>'summary'),actor)
  returning jsonb_build_object('id',id,'version',version) into result;
 elsif entity='pledge' then
  insert into outreach_private.pledges(id,engagement_id,kind,amount,description,promised_on,expected_on,status,created_by)
  values(ident,eng,p->>'kind',nullif(p->>'amount','')::numeric,trim(p->>'description'),(p->>'promised_on')::date,nullif(p->>'expected_on','')::date,p->>'status',actor)
  on conflict(id) do update set kind=excluded.kind,amount=excluded.amount,description=excluded.description,promised_on=excluded.promised_on,expected_on=excluded.expected_on,status=excluded.status,version=pledges.version+1,updated_at=clock_timestamp()
  returning jsonb_build_object('id',id,'version',version) into result;
 else
  insert into outreach_private.recognition(id,engagement_id,pledge_id,owner_id,kind,description,due_on,status,fulfilled_on,fulfillment_note,created_by)
  values(ident,eng,pledge,owner,p->>'kind',trim(p->>'description'),nullif(p->>'due_on','')::date,p->>'status',nullif(p->>'fulfilled_on','')::date,coalesce(p->>'fulfillment_note',''),actor)
  on conflict(id) do update set pledge_id=excluded.pledge_id,owner_id=excluded.owner_id,kind=excluded.kind,description=excluded.description,due_on=excluded.due_on,status=excluded.status,fulfilled_on=excluded.fulfilled_on,fulfillment_note=excluded.fulfillment_note,version=recognition.version+1,updated_at=clock_timestamp()
  returning jsonb_build_object('id',id,'version',version) into result;
 end if;
 execute format('select to_jsonb(t) from outreach_private.%I t where id=$1',table_name) into after_value using ident;
 insert into outreach_private.history(entity,entity_id,actor_id,request_id,action,before_data,after_data)
 values(entity,ident,actor,save.request_id,case when previous is null then 'created' else 'updated' end,previous,after_value);
 -- Preserve the exact request body separately from server-authored after_data.
 insert into outreach_private.requests(actor_id,request_id,operation,payload,result)
 values(actor,save.request_id,entity,input_payload,result);
 return result;
exception when others then
 -- CHECK/NOT NULL diagnostics can echo the proposed row, including restored
 -- private mentor notes. Sanitize at this directly executable private boundary,
 -- not just the public wrapper. Rethrowing preserves rollback and SQLSTATE.
 raise exception using errcode=sqlstate,
  message=case when sqlstate in ('42501','40001','22023') then sqlerrm else 'Outreach change rejected. Check the fields and refresh before retrying.' end,
  detail='',hint='';
end $function$

CREATE OR REPLACE FUNCTION pit_private.scouting_manage(action text, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare eid uuid; team integer; key text; v_kind text; aid uuid; rid uuid; ver integer;
 v_alliance text; v_station integer; station_target boolean:=false;
 prior_assignment public.pit_scouting_assignments; prior_pick public.pit_scouting_picklist; before_value jsonb; after_value jsonb;
begin
 perform pit_private.require_role(array['student','lead','admin_lead','mentor']);
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 if jsonb_typeof(p) is distinct from 'object' then raise exception 'Scouting management object required';end if;
 if action is null or action not in ('assignment','picklist') then raise exception 'Unknown scouting management action';end if;
 if exists(select 1 from jsonb_object_keys(p) k where not k=any(case when action='assignment' then array['event_id','kind','team_number','match_key','alliance','station','assignee_id','notes','version'] else array['event_id','team_number','rank','status','notes','version'] end)) then raise exception 'Unsupported scouting management fields';end if;
 eid:=(p->>'event_id')::uuid;
 if action='assignment' then
  v_kind:=p->>'kind';
  station_target:=coalesce(p->'alliance','null'::jsonb)<>'null'::jsonb or coalesce(p->'station','null'::jsonb)<>'null'::jsonb;
 end if;
 if station_target then
  if v_kind is distinct from 'match' then raise exception 'Driver station assignments must be match scouting';end if;
  if jsonb_typeof(p->'alliance') is distinct from 'string' or p->>'alliance' not in ('red','blue') then raise exception 'Driver station alliance must be red or blue';end if;
  if jsonb_typeof(p->'station') is distinct from 'number' then raise exception 'Driver station must be a whole number from 1 to 3';end if;
  if (p->>'station')::numeric<>trunc((p->>'station')::numeric) or (p->>'station')::numeric not between 1 and 3 then raise exception 'Driver station must be a whole number from 1 to 3';end if;
  if coalesce(p->'team_number','null'::jsonb)<>'null'::jsonb or coalesce(p->'match_key','null'::jsonb)<>'null'::jsonb then raise exception 'Driver station assignments cannot have a team number or match key';end if;
  v_alliance:=p->>'alliance';v_station:=(p->>'station')::numeric::integer;
 else
  if jsonb_typeof(p->'team_number') is distinct from 'number' then raise exception 'Team number must be a whole number from 1 to 99999';end if;
  if (p->>'team_number')::numeric<>trunc((p->>'team_number')::numeric) or (p->>'team_number')::numeric not between 1 and 99999 then raise exception 'Team number must be a whole number from 1 to 99999';end if;
  team:=(p->>'team_number')::integer;
 end if;
 if jsonb_typeof(p->'version') is distinct from 'number' then raise exception 'Scouting record changed. Refresh before saving';end if;
 if (p->>'version')::numeric<>trunc((p->>'version')::numeric) or (p->>'version')::numeric not between 0 and 2147483646 then raise exception 'Scouting record changed. Refresh before saving';end if;
 ver:=(p->>'version')::integer;
 if p?'notes' and (jsonb_typeof(p->'notes') is distinct from 'string' or length(p->>'notes')>2000) then raise exception 'Scouting notes must be at most 2000 characters';end if;
 perform pg_advisory_xact_lock(hashtextextended('pit-scouting-management:'||eid::text,0));
 -- Coordinate event identity with the existing configuration guard. Shared locks
 -- allow independent scouts to submit concurrently.
 perform pg_advisory_xact_lock_shared(hashtextextended('pit-scouting-event:'||eid::text,0));
 perform 1 from public.pit_events e where e.id=eid and e.status='active' for share;
 if not found then raise exception 'Select the active Pit event before managing scouting';end if;
 if action='assignment' then
  if not station_target then key:=pit_private.scouting_match_key(eid,v_kind,p->>'match_key');end if;
  aid:=nullif(p->>'assignee_id','')::uuid;
  if aid is not null and not exists(select 1 from public.profiles pr where pr.id=aid and pr.active and pr.role::text in ('student','lead','admin_lead','mentor')) then raise exception 'Assign an active scouting team member';end if;
  select * into prior_assignment from public.pit_scouting_assignments a
   where a.event_id=eid and a.kind=v_kind
    and ((station_target and a.alliance=v_alliance and a.station=v_station)
     or (not station_target and a.alliance is null and a.station is null and a.team_number=team and a.match_key is not distinct from key))
   for update;
  if found then
   if ver<>prior_assignment.version then raise exception 'Scouting assignment changed. Refresh before saving';end if;
   before_value:=to_jsonb(prior_assignment);
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   update public.pit_scouting_assignments set assignee_id=aid,notes=coalesce(p->>'notes',''),version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=prior_assignment.id returning id,to_jsonb(pit_scouting_assignments) into rid,after_value;
  else
   if ver<>0 then raise exception 'Scouting assignment changed. Refresh before saving';end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   insert into public.pit_scouting_assignments(event_id,kind,team_number,match_key,alliance,station,assignee_id,notes,updated_by) values(eid,v_kind,team,key,v_alliance,v_station,aid,coalesce(p->>'notes',''),auth.uid()) returning id,to_jsonb(pit_scouting_assignments) into rid,after_value;
  end if;
 else
  if jsonb_typeof(p->'rank') is distinct from 'number' then raise exception 'Picklist rank must be a whole number from 1 to 99999';end if;
  if (p->>'rank')::numeric<>trunc((p->>'rank')::numeric) or (p->>'rank')::numeric not between 1 and 99999 then raise exception 'Picklist rank must be a whole number from 1 to 99999';end if;
  if p->>'status' is null or p->>'status' not in ('available','picked','avoid') then raise exception 'Invalid picklist status';end if;
  select * into prior_pick from public.pit_scouting_picklist l where l.event_id=eid and l.team_number=team for update;
  if found then
   if ver<>prior_pick.version then raise exception 'Picklist changed. Refresh before saving';end if;
   before_value:=to_jsonb(prior_pick);
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   update public.pit_scouting_picklist set rank=(p->>'rank')::integer,status=p->>'status',notes=coalesce(p->>'notes',''),version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=prior_pick.id returning id,to_jsonb(pit_scouting_picklist) into rid,after_value;
  else
   if ver<>0 then raise exception 'Picklist changed. Refresh before saving';end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   insert into public.pit_scouting_picklist(event_id,team_number,rank,status,notes,updated_by) values(eid,team,(p->>'rank')::integer,p->>'status',coalesce(p->>'notes',''),auth.uid()) returning id,to_jsonb(pit_scouting_picklist) into rid,after_value;
  end if;
 end if;
 insert into public.pit_scouting_management_events(event_id,action,before_state,after_state,performed_by) values(eid,action,before_value,after_value,auth.uid());
 return rid;
end $function$

CREATE OR REPLACE FUNCTION pit_private.scouting_submit(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare rid uuid; eid uuid; sid uuid; team integer; key text; v_kind text; scout uuid;
 receipt pit_private.scouting_receipts; prior public.pit_scouting_observations;
begin
 perform pit_private.require_role(array['student','lead','admin_lead','mentor']);
 if jsonb_typeof(p) is distinct from 'object' or p->>'id' is null then raise exception 'Scouting request ID required';end if;
 rid:=(p->>'id')::uuid;
 -- Same UUID is serialized before receipt lookup, including a dropped response.
 perform pg_advisory_xact_lock(hashtextextended('pit-scouting-request:'||rid::text,0));
 select * into receipt from pit_private.scouting_receipts r where r.id=rid;
 if found then
  if receipt.actor_id is distinct from auth.uid() or receipt.request_payload is distinct from p then raise exception 'Request ID already used with a different scouting payload or actor';end if;
  return rid;
 end if;
 if exists(select 1 from jsonb_object_keys(p) k where not k=any(array['id','event_id','kind','team_number','match_key','data','supersedes_id'])) then raise exception 'Unsupported scouting request fields';end if;
 eid:=(p->>'event_id')::uuid; v_kind:=p->>'kind'; sid:=nullif(p->>'supersedes_id','')::uuid;
 if jsonb_typeof(p->'team_number') is distinct from 'number' then raise exception 'Team number must be a whole number from 1 to 99999';end if;
 if (p->>'team_number')::numeric<>trunc((p->>'team_number')::numeric) or (p->>'team_number')::numeric not between 1 and 99999 then raise exception 'Team number must be a whole number from 1 to 99999';end if;
 team:=(p->>'team_number')::integer;
 -- Coordinate event identity with the configuration guard below. Shared locks
 -- allow independent scouts to submit concurrently.
 perform pg_advisory_xact_lock_shared(hashtextextended('pit-scouting-event:'||eid::text,0));
 perform 1 from public.pit_events e where e.id=eid and e.status='active' for share;
 if not found then raise exception 'Select the active Pit event before submitting scouting';end if;
 key:=pit_private.scouting_match_key(eid,v_kind,p->>'match_key');
 perform pit_private.validate_scouting_data(v_kind,p->'data');
 scout:=auth.uid();
 if sid is not null then
  select * into prior from public.pit_scouting_observations o where o.id=sid for update;
  if not found then raise exception 'Scouting observation to correct was not found';end if;
  if prior.event_id<>eid or prior.kind<>v_kind or prior.team_number<>team or prior.match_key is distinct from key then raise exception 'Correction must keep the same event, team and match identity';end if;
  if prior.scout_id<>auth.uid() and not pit_private.competition_manager() then raise exception 'Only the original scout or active competition leadership may correct this observation' using errcode='42501';end if;
  if exists(select 1 from public.pit_scouting_observations o where o.supersedes_id=sid) then raise exception 'Observation already corrected. Refresh before submitting another correction';end if;
  scout:=prior.scout_id;
 elsif exists(select 1 from public.pit_scouting_observations o where o.event_id=eid and o.kind=v_kind and o.team_number=team and o.match_key is not distinct from key and o.scout_id=scout and o.supersedes_id is null) then
  raise exception 'You already submitted this team and match. Correct the existing observation';
 end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if sid is not null and prior.scout_id<>auth.uid() and not pit_private.competition_manager() then raise exception 'Only the original scout or active competition leadership may correct this observation' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
 insert into public.pit_scouting_observations(id,event_id,kind,team_number,match_key,data,supersedes_id,scout_id,created_by)
 values(rid,eid,v_kind,team,key,p->'data',sid,scout,auth.uid());
 insert into pit_private.scouting_receipts(id,actor_id,request_payload) values(rid,auth.uid(),p);
 return rid;
exception when unique_violation then
 raise exception 'Scouting observation already submitted or corrected. Refresh before submitting';
end $function$

CREATE OR REPLACE FUNCTION planning_review_private.decision_workflow_valid(v jsonb, previous_workflow jsonb, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item jsonb; field text; owner_id uuid; option_id uuid; chosen_id uuid; option_ids uuid[]:='{}';
 study jsonb; criterion jsonb; assessment jsonb; criterion_id uuid; criterion_ids uuid[]:='{}'; assessment_pairs text[]:='{}'; pair text;
begin
 if v is null then return;end if;
 perform planning_review_private.keys(v-'trade_study',array['schema_version','status','owner_id','target_date','decided_on','requirements','options','chosen_option_id','reopen_criteria']);
 if v->'schema_version' is distinct from '1'::jsonb or jsonb_typeof(v->'status') is distinct from 'string'
 or v->>'status' not in ('comparing','recorded','reopened') then raise exception using errcode='SR422',message='Invalid decision workflow';end if;
 owner_id:=planning_review_private.uid(v->'owner_id');
 if owner_id is not null and not exists(select 1 from public.profiles x where x.id=owner_id and x.active and x.role::text in ('student','lead','admin_lead'))
 and owner_id is distinct from planning_review_private.uid(coalesce(previous_workflow->'owner_id','null'::jsonb))
 then raise exception using errcode='SR422',message='Choose an active student decision owner';end if;
 foreach field in array array['target_date','decided_on'] loop
  if v->field is distinct from 'null'::jsonb then
   perform planning_review_private.text_field(v,field,10,true);
   if (v->>field)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or (v->>field)::date not between date '0001-01-01' and date '9999-12-31'
   then raise exception using errcode='SR422',message='Finite decision calendar date required';end if;
  end if;
 end loop;
 perform planning_review_private.references_valid(v->'requirements');
 perform planning_review_private.text_field(v,'reopen_criteria',2000);
 if jsonb_typeof(v->'options') is distinct from 'array' or jsonb_array_length(v->'options') not between 1 and 6
 then raise exception using errcode='SR422',message='Choose one to six decision options';end if;
 for item in select value from jsonb_array_elements(v->'options') loop
  perform planning_review_private.keys(item-'swot',array['id','label','description','weight','space','cost','reliability','time','evidence']);
  option_id:=planning_review_private.uid(item->'id');
  if option_id is null or option_id=any(option_ids) then raise exception using errcode='SR422',message='Unique decision option identity required';end if;
  option_ids:=array_append(option_ids,option_id);
  perform planning_review_private.text_field(item,'label',200,true);
  perform planning_review_private.text_field(item,'description',2000);
  foreach field in array array['weight','space','cost','reliability','time'] loop perform planning_review_private.text_field(item,field,1000);end loop;
  perform planning_review_private.references_valid(item->'evidence');
  if item ? 'swot' and item->'swot'<>'null'::jsonb then
   perform planning_review_private.keys(item->'swot',array['strengths','weaknesses','opportunities','threats']);
   foreach field in array array['strengths','weaknesses','opportunities','threats'] loop perform planning_review_private.text_field(item->'swot',field,2000);end loop;
  end if;
 end loop;
 -- Team-defined raw engineering measurements. No computed score or rank is persisted.
 -- Match the browser's finite IEEE-754 number representation, including ordered scale
 -- endpoints after rounding. Unrepresentable overflow/underflow raises a sanitized SR422.
 if v ? 'trade_study' and v->'trade_study'<>'null'::jsonb then
  study:=v->'trade_study';
  perform planning_review_private.keys(study,array['criteria','assessments']);
  if jsonb_typeof(study->'criteria') is distinct from 'array' or jsonb_array_length(study->'criteria')>8
  or jsonb_typeof(study->'assessments') is distinct from 'array' or jsonb_array_length(study->'assessments')>48
  then raise exception using errcode='SR422',message='Invalid trade study size';end if;
  for criterion in select value from jsonb_array_elements(study->'criteria') loop
   perform planning_review_private.keys(criterion,array['id','label','unit','weight','scale_min','scale_max','direction','must_have','minimum','maximum']);
   criterion_id:=planning_review_private.uid(criterion->'id');
   if criterion_id is null or criterion_id=any(criterion_ids) then raise exception using errcode='SR422',message='Unique criterion identity required';end if;
   criterion_ids:=array_append(criterion_ids,criterion_id);
   perform planning_review_private.text_field(criterion,'label',200,true);
   perform planning_review_private.text_field(criterion,'unit',50,true);
   if jsonb_typeof(criterion->'weight') is distinct from 'number' or (criterion->>'weight')::double precision not between 0 and 1000
   then raise exception using errcode='SR422',message='Invalid criterion weight';end if;
   foreach field in array array['scale_min','scale_max','minimum','maximum'] loop
    if field in ('scale_min','scale_max') or criterion->field<>'null'::jsonb then
     if jsonb_typeof(criterion->field) is distinct from 'number' or (criterion->>field)::double precision not between -1000000000000 and 1000000000000
     then raise exception using errcode='SR422',message='Invalid measurement bound';end if;
    end if;
   end loop;
   if (criterion->>'scale_min')::double precision>=(criterion->>'scale_max')::double precision
   or jsonb_typeof(criterion->'direction') is distinct from 'string' or criterion->>'direction' not in ('higher','lower')
   or jsonb_typeof(criterion->'must_have') is distinct from 'boolean'
   then raise exception using errcode='SR422',message='Invalid normalization definition';end if;
   if (criterion->>'must_have')::boolean then
    if criterion->'minimum'='null'::jsonb and criterion->'maximum'='null'::jsonb
    then raise exception using errcode='SR422',message='A hard constraint requires a minimum or maximum';end if;
   elsif criterion->'minimum'<>'null'::jsonb or criterion->'maximum'<>'null'::jsonb
   then raise exception using errcode='SR422',message='Unmarked hard constraint';end if;
   if criterion->'minimum'<>'null'::jsonb and criterion->'maximum'<>'null'::jsonb and (criterion->>'minimum')::double precision>(criterion->>'maximum')::double precision
   then raise exception using errcode='SR422',message='Invalid hard constraint bounds';end if;
  end loop;
  for assessment in select value from jsonb_array_elements(study->'assessments') loop
   perform planning_review_private.keys(assessment,array['option_id','criterion_id','value','reason','evidence']);
   option_id:=planning_review_private.uid(assessment->'option_id');criterion_id:=planning_review_private.uid(assessment->'criterion_id');
   if option_id is null or criterion_id is null
   or not exists(select 1 from jsonb_array_elements(v->'options') x where x->>'id'=assessment->>'option_id')
   or not exists(select 1 from jsonb_array_elements(study->'criteria') x where x->>'id'=assessment->>'criterion_id')
   then raise exception using errcode='SR422',message='Assessment must reference this comparison';end if;
   pair:=option_id::text||':'||criterion_id::text;
   if pair=any(assessment_pairs) then raise exception using errcode='SR422',message='Duplicate option criterion assessment';end if;
   assessment_pairs:=array_append(assessment_pairs,pair);
   if assessment->'value'<>'null'::jsonb and (jsonb_typeof(assessment->'value') is distinct from 'number' or (assessment->>'value')::double precision not between -1000000000000 and 1000000000000)
   then raise exception using errcode='SR422',message='Invalid raw measurement';end if;
   perform planning_review_private.text_field(assessment,'reason',2000);
   perform planning_review_private.references_valid(assessment->'evidence');
  end loop;
 end if;
 chosen_id:=planning_review_private.uid(v->'chosen_option_id');
 if chosen_id is not null and not exists(select 1 from jsonb_array_elements(v->'options') x where x->>'id'=v->>'chosen_option_id')
 then raise exception using errcode='SR422',message='Chosen option must be in the comparison';end if;
 if v->>'status'='recorded' then
  if owner_id is null or v->'decided_on'='null'::jsonb or chosen_id is null or jsonb_array_length(p->'reported_by_student_ids')=0
  then raise exception using errcode='SR422',message='Complete the reported student decision';end if;
  perform planning_review_private.text_field(p,'reported_decision',5000,true);
  perform planning_review_private.text_field(p,'decision_rationale',5000,true);
  perform planning_review_private.text_field(v,'reopen_criteria',2000,true);
 end if;
end $function$

CREATE OR REPLACE FUNCTION private.can_manage_media(kind text, entity uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.profiles;
begin
 -- Serialize photo authorization with role/area revocation for this transaction.
 select * into actor from public.profiles where id=auth.uid() and active for share;
 if not found then return false;end if;
 if kind='items' then
  return actor.role::text in ('student','lead','admin_lead','mentor') and exists(select 1 from public.inventory_items where id=entity);
 elsif kind='locations' then
  return exists(select 1 from public.locations where id=entity and (actor.role::text='mentor' or (actor.role::text in ('lead','admin_lead') and area_id=actor.primary_area_id)));
 end if;
 return false;
end
$function$

CREATE OR REPLACE FUNCTION private.guard_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := auth.uid();
begin
 if actor is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if tg_op='INSERT' or new.location_id is distinct from old.location_id then
  -- Serialize drawer membership changes with audit verification (including new arrivals).
  if new.location_id is not null then perform pg_advisory_xact_lock(hashtextextended(new.location_id::text,4418));end if;
  if tg_op='UPDATE' and old.location_id is not null then perform pg_advisory_xact_lock(hashtextextended(old.location_id::text,4418));end if;
 end if;
 -- Current authority is checked after business locks and held through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text in ('student','lead','admin_lead','mentor') for share;
 if not found then raise exception 'You cannot change inventory' using errcode='42501';end if;
 if tg_op='INSERT' then
  if not coalesce(private.can_create_item(new.area_id),false) then raise exception 'You cannot create items in this area' using errcode='42501';end if;
  new.created_by:=actor; new.created_at:=clock_timestamp();
  -- Imported historical verification dates may be preserved by mentors; no verifier is invented.
  new.last_verified_by:=null;
 else
  if not private.can_count() then raise exception 'You cannot change inventory' using errcode='42501';end if;
  if new.area_id is distinct from old.area_id and not private.is_admin() then raise exception 'Only a Mentor can reassign an existing item to another team area' using errcode='42501';end if;
  if new.id<>old.id or new.created_at<>old.created_at or new.created_by is distinct from old.created_by then raise exception 'Item identity is immutable' using errcode='42501';end if;
  if (to_jsonb(new)-array['quantity','last_verified_at','last_verified_by','updated_at','updated_by']) is distinct from (to_jsonb(old)-array['quantity','last_verified_at','last_verified_by','updated_at','updated_by']) then
   if not coalesce(private.can_edit(old.area_id) and private.can_edit(new.area_id),false) then raise exception 'An active Student, Lead, Admin Lead or Mentor is required to edit items' using errcode='42501';end if;
  end if;
  if new.last_verified_at is distinct from old.last_verified_at then new.last_verified_at:=clock_timestamp();new.last_verified_by:=actor;
  else new.last_verified_by:=old.last_verified_by;end if;
 end if;
 new.updated_by:=actor;new.updated_at:=clock_timestamp();return new;
end $function$

CREATE OR REPLACE FUNCTION private.rename_inventory_location(p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare target public.locations; target_id uuid:=nullif(p_data->>'id','')::uuid;
 expected timestamptz:=nullif(p_data->>'updatedAt','')::timestamptz;
 next_name text:=trim(coalesce(p_data->>'name',''));
begin
 perform pg_advisory_xact_lock(4418);
 if not (private.can_rename_location()) then
  raise exception 'An Admin Lead, Mentor or active assigned functional lead is required to rename locations' using errcode='42501';
 end if;
 if jsonb_typeof(p_data) is distinct from 'object' or exists(
  select 1 from jsonb_object_keys(p_data) key where key not in ('id','name','updatedAt')
 ) then raise exception 'Renaming changes only the location name' using errcode='22023';end if;
 if length(next_name) not between 1 and 200 or next_name !~ '[^[:space:]]' or next_name ~ '[[:cntrl:]]' then raise exception 'Enter a location name up to 200 characters' using errcode='22023';end if;
 perform pg_advisory_xact_lock(4419);
 select * into target from public.locations l where l.id=target_id for update;
 if not found or exists(
  with recursive ancestors as (
   select l.id,l.parent_id,l.active,l.trip_id,l.classification from public.locations l where l.id=target_id
   union select l.id,l.parent_id,l.active,l.trip_id,l.classification from public.locations l join ancestors a on l.id=a.parent_id
  ) select 1 from ancestors where id='44180000-0000-4000-8000-000000000099'::uuid or not active
   or trip_id is not null or classification not in ('permanent','project','robot','temporary','other')
 ) then raise exception 'Only active normal storage locations can be renamed' using errcode='42501';end if;
 if expected is null or target.updated_at is distinct from expected then
  raise exception 'This location changed. Close and reopen Rename before trying again.' using errcode='40001';
 end if;
 -- A committed role/position loss while waiting cannot reuse earlier permission.
 perform 1 from public.profiles where id=auth.uid() and active and role::text in ('student','lead','admin_lead','mentor') for share;
 if not found then raise exception 'No permission to rename locations' using errcode='42501';end if;
 if private.current_role() in ('student','lead') then
  perform 1 from public.team_member_positions mp join public.team_positions pos on pos.key=mp.position_key and pos.active where mp.user_id=auth.uid() and mp.revoked_at is null for share of mp,pos;
 end if;
 if not private.can_rename_location() then raise exception 'No permission to rename locations' using errcode='42501';end if;
 if target.name is distinct from next_name then update public.locations set name=next_name where id=target.id;end if;
 return jsonb_build_object('id',target.id);
end
$function$

CREATE OR REPLACE FUNCTION public.apply_inventory_changes(p_changes jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r jsonb; payload jsonb; existing public.inventory_items; value public.inventory_items;
begin
 for r in select * from jsonb_array_elements(coalesce(p_changes->'areas','[]')) loop
  payload:=r->'record';
  insert into public.areas(id,slug,name,lead_name,active) values((payload->>'id')::uuid,payload->>'slug',payload->>'name',coalesce(payload->>'lead_name',''),true)
  on conflict(id) do update set name=excluded.name,lead_name=excluded.lead_name,updated_at=clock_timestamp();
 end loop;
 for r in select * from jsonb_array_elements(coalesce(p_changes->'locations','[]')) loop
  payload:=r->'record';
  insert into public.locations(id,name,code,parent_id,location_type,description,room,storage,classification,area_id) values((payload->>'id')::uuid,payload->>'name',payload->>'code',(payload->>'parent_id')::uuid,payload->>'location_type',payload->>'description',coalesce(payload->>'room',''),coalesce(payload->>'storage',''),coalesce(payload->>'classification','permanent'),nullif(payload->>'area_id','')::uuid)
  on conflict(id) do update set name=excluded.name,code=excluded.code,parent_id=excluded.parent_id,location_type=excluded.location_type,description=excluded.description,room=excluded.room,storage=excluded.storage,classification=excluded.classification,area_id=excluded.area_id;
 end loop;
 for r in select * from jsonb_array_elements(coalesce(p_changes->'categories','[]')) loop
  insert into public.categories(name) values(r#>>'{}') on conflict do nothing;
 end loop;
 for r in select * from jsonb_array_elements(coalesce(p_changes->'items','[]')) loop
  payload:=r->'record';
  select * into existing from public.inventory_items where id=(payload->>'id')::uuid for update;
  if found then
   -- A row lock may have waited across a committed role downgrade. Do not
   -- let RLS silently turn an intended save into a zero-row success response.
   perform 1 from public.profiles where id=auth.uid() and active and role::text in ('student','lead','admin_lead','mentor');
   if not found then raise exception 'You cannot change inventory' using errcode='42501';end if;
   if r->>'expected_updated_at' is null or existing.updated_at<>(r->>'expected_updated_at')::timestamptz then raise exception 'An item changed on another device. Refresh and retry.' using errcode='40001';end if;
   value:=jsonb_populate_record(existing,payload);
   update public.inventory_items set name=value.name,item_type=value.item_type,ownership=value.ownership,area_id=value.area_id,category=value.category,quantity=value.quantity,expected_quantity=value.expected_quantity,minimum_quantity=value.minimum_quantity,target_quantity=value.target_quantity,unit=value.unit,location_id=value.location_id,slot_position=value.slot_position,manufacturer=value.manufacturer,manufacturer_part_number=value.manufacturer_part_number,vendor=value.vendor,vendor_url=value.vendor_url,approx_unit_cost=value.approx_unit_cost,notes=value.notes,last_verified_at=value.last_verified_at,legacy_updated_by=value.legacy_updated_by,order_status=value.order_status,tracking_mode=value.tracking_mode where id=existing.id;
   if not found then raise exception 'You cannot change inventory' using errcode='42501';end if;
  else
   if r->>'expected_updated_at' is not null then raise exception 'An item was removed on another device. Refresh and retry.' using errcode='40001';end if;
   value:=jsonb_populate_record(null::public.inventory_items,payload);
   insert into public.inventory_items(id,name,item_type,ownership,area_id,category,quantity,expected_quantity,minimum_quantity,target_quantity,unit,location_id,slot_position,manufacturer,manufacturer_part_number,vendor,vendor_url,approx_unit_cost,notes,last_verified_at,legacy_updated_by,order_status,tracking_mode)
   values(value.id,value.name,value.item_type,value.ownership,value.area_id,value.category,value.quantity,value.expected_quantity,value.minimum_quantity,value.target_quantity,value.unit,value.location_id,value.slot_position,value.manufacturer,value.manufacturer_part_number,value.vendor,value.vendor_url,value.approx_unit_cost,value.notes,value.last_verified_at,value.legacy_updated_by,value.order_status,value.tracking_mode);
  end if;
 end loop;
 for r in select * from jsonb_array_elements(coalesce(p_changes->'deleted_items','[]')) loop
  select * into existing from public.inventory_items where id=(r->>'id')::uuid for update;
  if not found or r->>'updated_at' is null or existing.updated_at<>(r->>'updated_at')::timestamptz then raise exception 'An item changed on another device. Refresh and retry.' using errcode='40001';end if;
  if not coalesce(private.can_delete_item(existing.area_id),false) then raise exception 'You cannot delete this item' using errcode='42501';end if;
  delete from public.inventory_items where id=existing.id;
  if not found then raise exception 'You cannot delete this item' using errcode='42501';end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.change_inventory_quantity(p_id uuid, p_delta numeric DEFAULT NULL::numeric, p_quantity numeric DEFAULT NULL::numeric, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_verify boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare current_item public.inventory_items; saved public.inventory_items; amount numeric;
begin
 if not private.can_count() then raise exception 'You do not have permission to change quantities' using errcode='42501';end if;
 if (p_delta is null)=(p_quantity is null) then raise exception 'Provide a delta or an absolute quantity';end if;
 select * into strict current_item from public.inventory_items where id=p_id for update;
 -- Re-read committed authority after the item-lock wait; do not reuse a pre-wait helper result.
 if not exists(select 1 from public.profiles where id=auth.uid() and active and role::text in ('student','lead','admin_lead','mentor')) then
  raise exception 'You do not have permission to change inventory' using errcode='42501';
 end if;
 if p_delta is null and (p_expected_updated_at is null or current_item.updated_at<>p_expected_updated_at) then raise exception 'This item changed on another device. Refresh and try again.' using errcode='40001';end if;
 amount:=case when p_delta is null then p_quantity else greatest(0,current_item.quantity+p_delta) end;
 update public.inventory_items set quantity=amount,last_verified_at=case when p_verify then clock_timestamp() else last_verified_at end where id=p_id returning * into saved;
 return jsonb_build_object('before',current_item.quantity,'item',to_jsonb(saved));
end $function$

CREATE OR REPLACE FUNCTION public.finance_notification_delivery_allowed(notification_id uuid, token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 n public.team_notifications;
 h finance_private.history;
 po public.finance_purchase_orders;
 recipient public.profiles;
 positions text[];
 is_school_submitter boolean;
 is_finance_admin boolean;
 is_requester boolean;
 has_approved boolean;
 allowed boolean := false;
begin
 -- Bind the decision to the server-owned row and the current delivery lease.
 -- Neither an actor ID nor notification payload is an authorization input.
 select * into n from public.team_notifications
 where id = notification_id and source = 'finance' and entity_type = 'finance_po'
   and channel = 'email' and status = 'sending' and lease_token = token;
 if not found then return false; end if;
 -- A slow check must not permanently skip an otherwise eligible recipient.
 -- The worker records RPC errors as retry; a superseded token cannot finish.
 if n.lease_until is null or n.lease_until <= clock_timestamp() then
  raise exception 'Delivery lease expired';
 end if;
 select * into h from finance_private.history
 where id = n.source_event_id and po_id = n.entity_id;
 if not found then return false; end if;
 select * into po from public.finance_purchase_orders where id = n.entity_id;
 if not found then return false; end if;
 select * into recipient from public.profiles where id = n.recipient_id
   and active and role::text in ('student','lead','admin_lead','mentor');
 if not found then return false; end if;

 select coalesce(array_agg(mp.position_key), '{}') into positions
 from public.team_member_positions mp
 join public.team_positions p on p.key = mp.position_key and p.active
 where mp.user_id = recipient.id and mp.revoked_at is null;
 select recipient.role::text='admin_lead' or exists(select 1 from public.finance_assignments a
   where a.user_id = recipient.id and a.capability = 'school_submitter' and a.active),
   exists(select 1 from public.finance_assignments a
   where a.user_id = recipient.id and a.capability = 'finance_admin' and a.active)
 into is_school_submitter, is_finance_admin;

 -- Match finance_private.visible for this explicit recipient, without changing
 -- auth.uid()/JWT state in a service-role request. Approver capabilities come
 -- from live Team Hub positions, never the legacy Finance assignment slots.
 if not coalesce((po.requester_id = recipient.id or recipient.role::text in ('mentor')
   or is_finance_admin or (po.status <> 'draft' and
     (positions && array['finance_lead','lead_coach_1','lead_coach_2']
      or is_school_submitter
      or (recipient.role::text in ('lead','admin_lead') and po.area_id = recipient.primary_area_id)))), false) then
  return false;
 end if;

 is_requester := recipient.id = po.requester_id
   and h.details->'after'->>'requester_id' = recipient.id::text;
 select exists(select 1 from public.finance_po_approvals a
   where a.po_id = po.id and a.revision = h.revision and a.action = 'approved'
     and a.actor_id = recipient.id) into has_approved;

 -- Re-evaluate the queued event's audience against current authority. The
 -- historical event, not the frozen display payload, identifies that audience.
 case n.event
 when 'approval_needed' then
  allowed := h.action = 'submit' and not is_requester and not has_approved
    and positions && array['finance_lead','lead_coach_1','lead_coach_2'];
 when 'approval_remaining', 'approval_recorded' then
  allowed := h.action = 'approve' and h.details->'after'->>'status' = 'awaiting_approval'
    and ((n.event = 'approval_recorded' and is_requester)
      or (not is_requester and not has_approved and
        case h.details->>'slot'
        when 'po_approver' then positions && array['finance_lead']
        when 'finance_approver' then positions && array['lead_coach_1','lead_coach_2']
        else false end));
 when 'changes_requested' then
  allowed := h.action = 'request_changes' and is_requester;
 when 'ready_for_school' then
  allowed := h.action = 'approve' and h.details->'after'->>'status' = 'approved'
    and (is_requester or is_school_submitter or
      (recipient.role::text in ('mentor')
       and not exists(select 1 from public.profiles p where p.active and p.role::text='admin_lead')
       and not exists(select 1 from public.finance_assignments a
         join public.profiles p on p.id = a.user_id and p.active
           and p.role::text in ('student','lead','admin_lead','mentor')
         where a.capability = 'school_submitter' and a.active)
       and (select count(*) from public.profiles p
         where p.active and p.role::text in ('mentor')) <= 5));
 when 'submitted_to_school' then
  allowed := h.action = 'school_submit' and (is_requester or has_approved);
 when 'cancelled' then
  allowed := h.action = 'cancel' and (is_requester or (h.revision > 0 and
    (positions && array['finance_lead','lead_coach_1','lead_coach_2']
     or exists(select 1 from public.finance_po_approvals a
       where a.po_id = po.id and a.revision = h.revision and a.actor_id = recipient.id))));
 else
  return false;
 end case;
 return coalesce(allowed, false);
end $function$

CREATE OR REPLACE FUNCTION public.finance_repair_context(p_issue_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  issue_stamp timestamptz;
  pit_role text := pit_private.current_role();
begin
  if not coalesce(pit_role = any(array['readonly','student','lead','admin_lead','mentor']), false) then
    raise exception 'Repair purchasing details unavailable' using errcode = '42501';
  end if;
  select i.updated_at into issue_stamp from public.pit_issues i where i.id = p_issue_id;
  if not found then
    raise exception 'Repair purchasing details unavailable' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'issue_id', p_issue_id,
    'issue_updated_at', issue_stamp,
    'can_attach', pit_role = any(array['lead','admin_lead','mentor']),
    'links', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'po_id', po.id, 'po_number', po.po_number, 'status', po.status,
        'requester_name', coalesce(nullif(trim(pr.display_name), ''), 'Team member'),
        'linked_at', l.linked_at
      ) order by l.linked_at, po.id), '[]'::jsonb)
      from finance_private.repair_po_links l
      join public.finance_purchase_orders po on po.id = l.po_id
      join public.profiles pr on pr.id = po.requester_id
      where l.issue_id = p_issue_id and finance_private.visible(po.id)
    )
  );
end $function$

CREATE OR REPLACE FUNCTION public.finance_repair_po_candidate(p_issue_id uuid, p_po_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  issue_stamp timestamptz;
  po public.finance_purchase_orders;
  requester_name text;
  pit_role text := pit_private.current_role();
begin
  if not coalesce(pit_role = any(array['readonly','student','lead','admin_lead','mentor']), false) then
    raise exception 'Repair purchasing details unavailable' using errcode = '42501';
  end if;
  select i.updated_at into issue_stamp from public.pit_issues i where i.id = p_issue_id;
  if not found or not coalesce(finance_private.visible(p_po_id), false) then
    raise exception 'Repair purchasing details unavailable' using errcode = '42501';
  end if;
  select * into po from public.finance_purchase_orders where id = p_po_id;
  if not found then
    raise exception 'Repair purchasing details unavailable' using errcode = '42501';
  end if;
  select coalesce(nullif(trim(pr.display_name), ''), 'Team member') into requester_name
    from public.profiles pr where pr.id = po.requester_id;
  return jsonb_build_object(
    'issue_id', p_issue_id, 'issue_updated_at', issue_stamp,
    'po_id', po.id, 'po_number', po.po_number, 'status', po.status,
    'requester_name', requester_name,
    'can_attach', pit_role = any(array['lead','admin_lead','mentor'])
      and (po.requester_id = auth.uid() or finance_private.admin())
  );
end $function$

CREATE OR REPLACE FUNCTION public.inventory_action(p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); i public.inventory_items; t public.trips; m public.trip_manifest_items; source public.locations; dest public.locations;
 iid uuid;tid uuid;src uuid;dst uuid;mid uuid; qty numeric;have numeric;other numeric;new_id uuid;note text:=coalesce(p_data->>'note','');action_type text;new_status text;part record;oldqty numeric;
begin
 if not private.can_count() then raise exception 'You do not have permission for this action' using errcode='42501';end if;
 if p_action='create_location' then
  return private.create_assigned_lead_location(p_data);
 end if;
 if p_action='configure_location' then
  return private.configure_inventory_location(p_data);
 end if;
 if p_action='rename_location' then
  return private.rename_inventory_location(p_data);
 end if;
 if p_action='create_trip' then
  if not private.is_admin() then raise exception 'Only mentors create trips' using errcode='42501';end if;
  insert into public.trips(name,event_name,destination,start_date,end_date,notes,created_by) values(trim(p_data->>'name'),coalesce(p_data->>'event',''),coalesce(p_data->>'destination',''),nullif(p_data->>'start','')::date,nullif(p_data->>'end','')::date,note,actor) returning id into tid;
  insert into public.locations(name,code,location_type,classification,trip_id) values(p_data->>'name',p_data->>'name','Storage','travel',tid) returning id into src;
  foreach action_type in array array['Trailer','Pit Toolbox A','Pit Toolbox B','Robot Cart','Programming Case','Battery Cart'] loop
   insert into public.locations(name,code,location_type,parent_id,classification,trip_id) values(action_type,action_type,'Storage',src,'travel',tid);
  end loop;return jsonb_build_object('id',tid);
 end if;
 tid:=nullif(p_data->>'tripId','')::uuid;mid:=nullif(p_data->>'manifestId','')::uuid;
 if mid is not null then select trip_id into strict tid from public.trip_manifest_items where id=mid;end if;
 if tid is not null then
  select * into strict t from public.trips where id=tid for update;
  if t.status in ('closed','cancelled') then raise exception 'This trip is archived';end if;
 end if;
 if p_action='trip_status' then
  if not private.is_admin() then raise exception 'Only mentors manage trips' using errcode='42501';end if;
  new_status:=p_data->>'status';
  if new_status in ('closed','cancelled') then
   if exists(select 1 from public.trip_manifest_items where trip_id=tid and status in ('approved','packed')) then raise exception 'Unresolved manifest items remain. Return them or explicitly resolve each item first.';end if;
   if exists(select 1 from public.inventory_balances b join public.locations l on l.id=b.location_id where l.trip_id=tid and b.quantity>0) then raise exception 'Travel locations still contain stock';end if;
   perform set_config('app.trip_write','yes',true);update public.locations set active=false where trip_id=tid;perform set_config('app.trip_write','',true);
  end if;
  update public.trips set status=new_status,updated_at=clock_timestamp(),notes=notes||case when note<>'' then E'\n'||note else '' end where id=tid;
  insert into public.inventory_movements(item_name,quantity,trip_id,movement_type,user_id,note) values(t.name,0,tid,'resolution',actor,'Trip status: '||new_status||'. '||note);
  return '{}'::jsonb;
 end if;
 if p_action in ('pack','internal','return','resolve') and mid is null then raise exception 'An approved manifest allocation is required';end if;
 iid:=nullif(p_data->>'itemId','')::uuid;
 if mid is not null then select * into strict m from public.trip_manifest_items where id=mid for update;iid:=m.inventory_item_id;end if;
 select * into strict i from public.inventory_items where id=iid for update;
 -- Re-read committed authority after the item-lock wait; do not reuse a pre-wait helper result.
 if not exists(select 1 from public.profiles where id=auth.uid() and active and role::text in ('student','lead','admin_lead','mentor')) then
  raise exception 'You do not have permission to change inventory' using errcode='42501';
 end if;
 qty:=(p_data->>'quantity')::numeric;src:=nullif(p_data->>'from','')::uuid;dst:=nullif(p_data->>'to','')::uuid;
 if mid is not null then src:=case when m.status='approved' then m.home_location_id else m.current_location_id end;end if;
 if p_action='return' then dst:=m.home_location_id;end if;
 if p_action='pack' then dst:=m.current_location_id;end if;
 if p_action in ('approve','pack','internal','return','resolve') and tid is null then raise exception 'A trip is required';end if;
 if p_action in ('pack','internal','return') and t.status='planning' then raise exception 'Start packing before moving trip inventory';end if;
 if p_action='approve' then
  if not(private.is_admin() or private.current_role() in ('lead','admin_lead')) then raise exception 'A lead or mentor must approve manifest items' using errcode='42501';end if;
  if t.status not in ('planning','packing') then raise exception 'Approve items during planning or packing';end if;
 end if;
 if p_action='resolve' then
  if not private.is_admin() or trim(note)='' then raise exception 'A mentor and a resolution note are required';end if;
  if m.status not in ('approved','packed') then raise exception 'This allocation is already resolved';end if;
  if m.status='approved' then
   if qty is null or qty<=0 or qty>m.quantity then raise exception 'Quantity exceeds this approval';end if;
   if qty<m.quantity then
    update public.trip_manifest_items set quantity=quantity-qty,updated_at=clock_timestamp() where id=mid;
    insert into public.trip_manifest_items(trip_id,inventory_item_id,quantity,home_location_id,current_location_id,ownership,status,resolution,notes) values(tid,i.id,qty,m.home_location_id,m.current_location_id,m.ownership,'resolved','Not packed: '||note,m.notes);
   else update public.trip_manifest_items set status='resolved',resolution='Not packed: '||note,updated_at=clock_timestamp() where id=mid;end if;
   insert into public.inventory_movements(inventory_item_id,item_name,quantity,trip_id,movement_type,user_id,note) values(i.id,i.name,0,tid,'resolution',actor,'Unpacked approval resolved: '||note);return '{}'::jsonb;
  end if;
  if p_data->>'resolution' not in ('lost','consumed','transferred','manual') then raise exception 'Choose a resolution';end if;
  if p_data->>'resolution' in ('lost','consumed') then dst:=null;elsif dst is null then raise exception 'Select the actual non-travel destination';end if;
 end if;
 select coalesce(sum(quantity),0) into have from public.inventory_balances where inventory_item_id=i.id and location_id=src;
 if p_action='adjust' and p_data->>'delta' is not null then qty:=greatest(0,have+(p_data->>'delta')::numeric);end if;
 if p_action='adjust' then
  if qty is null or qty<0 or qty>='Infinity'::numeric then raise exception 'Enter a finite nonnegative count';end if;
 else
  if qty is null or qty<=0 or qty>='Infinity'::numeric then raise exception 'Enter a finite quantity greater than zero';end if;
 end if;
 select * into strict source from public.locations where id=src and active for share;
 if dst is not null then select * into strict dest from public.locations where id=dst and active for share;end if;
 if p_action in ('move','adjust') and (source.trip_id is not null or dest.trip_id is not null) then raise exception 'Use the trip manifest for travel inventory';end if;
 if p_action='approve' and (source.trip_id is not null or dest.trip_id is distinct from tid) then raise exception 'Choose a non-travel home and a location in this trip';end if;
 if p_action in ('pack','internal') and dest.trip_id is distinct from tid then raise exception 'Destination must belong to this trip';end if;
 if p_action in ('internal','return','resolve') and source.trip_id is distinct from tid then raise exception 'Source must belong to this trip';end if;
 if p_action='resolve' and dst is not null and dest.trip_id is not null then raise exception 'Resolve to a non-travel location';end if;
 if p_action='approve' then
  insert into public.trip_manifest_items(trip_id,inventory_item_id,quantity,home_location_id,current_location_id,ownership,status,notes) values(tid,i.id,qty,src,dst,i.ownership,'approved',note) returning id into new_id;
  insert into public.inventory_movements(inventory_item_id,item_name,quantity,trip_id,movement_type,user_id,note) values(i.id,i.name,0,tid,'resolution',actor,'Approved '||qty||' for packing. '||note);return jsonb_build_object('id',new_id);
 end if;
 select coalesce(sum(quantity),0) into have from public.inventory_balances where inventory_item_id=i.id and location_id=src;
 if p_action='adjust' then
  if p_data->>'delta' is null and i.updated_at is distinct from (p_data->>'updatedAt')::timestamptz then raise exception 'Item changed. Review the latest counts before correcting.' using errcode='40001';end if;
  perform private.balance_set(i.id,src,qty);
  insert into public.inventory_movements(inventory_item_id,item_name,quantity,from_location_id,to_location_id,movement_type,user_id,note) values(i.id,i.name,abs(qty-have),case when qty<have then src end,case when qty>have then src end,'adjustment',actor,note);
  if coalesce((p_data->>'verify')::boolean,false) then update public.inventory_balances set last_verified_at=clock_timestamp(),last_verified_by=actor where inventory_item_id=i.id and location_id=src;end if;
  perform private.balance_sync(i.id);
  if coalesce((p_data->>'verify')::boolean,false) then
   if i.location_id is distinct from src then insert into public.inventory_events(inventory_item_id,item_name,area_id,user_id,event_type,notes) values(i.id,i.name,i.area_id,actor,'item_verified',src::text);end if;
   if i.location_id=src then perform set_config('app.balance_sync','yes',true);update public.inventory_items set last_verified_at=clock_timestamp() where id=i.id;perform set_config('app.balance_sync','',true);end if;
  end if;
  return jsonb_build_object('before',have,'quantity',qty,'item',(select to_jsonb(x) from public.inventory_items x where id=i.id));
 end if;
 if dst is null and p_action<>'resolve' then raise exception 'A destination is required';end if;
 if src=dst then raise exception 'Source and destination must differ';end if;
 if qty>have then raise exception 'Not enough quantity at the source';end if;
 if p_action in ('pack','internal','return','resolve') then
  if (p_action='pack' and m.status<>'approved') or (p_action<>'pack' and m.status<>'packed') or qty>m.quantity then raise exception 'Allocation changed or quantity exceeds this manifest allocation';end if;
  new_status:=case when p_action='return' then 'returned' when p_action='resolve' then 'resolved' else 'packed' end;
  if qty<m.quantity then
   update public.trip_manifest_items set quantity=quantity-qty,updated_at=clock_timestamp() where id=mid;
   insert into public.trip_manifest_items(trip_id,inventory_item_id,quantity,home_location_id,current_location_id,ownership,status,resolution,notes) values(tid,i.id,qty,m.home_location_id,coalesce(dst,src),m.ownership,new_status,case when p_action='resolve' then (p_data->>'resolution')||': '||note else '' end,m.notes);
  else update public.trip_manifest_items set current_location_id=coalesce(dst,src),status=new_status,resolution=case when p_action='resolve' then (p_data->>'resolution')||': '||note else '' end,updated_at=clock_timestamp() where id=mid;end if;
 end if;
 action_type:=case p_action when 'move' then 'transfer' when 'pack' then 'trip_pack' when 'internal' then 'trip_internal_move' when 'return' then 'trip_return' when 'resolve' then 'resolution' else null end;
 if action_type is null then raise exception 'Unknown inventory action';end if;
 perform private.balance_set(i.id,src,have-qty);
 if dst is not null then
  select coalesce(sum(quantity),0) into other from public.inventory_balances where inventory_item_id=i.id and location_id=dst;perform private.balance_set(i.id,dst,other+qty);
 end if;
 insert into public.inventory_movements(inventory_item_id,item_name,quantity,from_location_id,to_location_id,trip_id,movement_type,user_id,note) values(i.id,i.name,qty,src,dst,tid,action_type,actor,case when p_action='resolve' then (p_data->>'resolution')||': ' else '' end||note);
 perform private.balance_sync(i.id);
 return '{}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.pit_competition_manage(action text, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare eid uuid:=nullif(p->>'event_id','')::uuid;mid uuid:=nullif(p->>'match_id','')::uuid;rid uuid:=nullif(p->>'id','')::uuid;
 c public.pit_event_config;m public.pit_match_ops;t public.pit_checklist_templates;r public.pit_checklist_runs;i public.pit_checklist_run_items;
 item jsonb;idx integer:=0;bid uuid;issue public.pit_issues;new_id uuid;
 manual_name text;manual_time timestamptz;manual_note text;creation public.pit_manual_match_events;
 after_match jsonb;archive_target boolean;manual_action text;
begin
 perform pg_advisory_xact_lock(4418,30);
 perform pit_private.require_role(array['student','lead','admin_lead','mentor']);
 if action in ('config','template','match','manual_match','finish_manual_match','archive_manual_match') and not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 if action='template' then
  if jsonb_typeof(p->'items') is distinct from 'array' or jsonb_array_length(p->'items') not between 1 and 60 then raise exception 'Add 1–60 checklist items';end if;
  for item in select value from jsonb_array_elements(p->'items') loop
   if length(trim(coalesce(item->>'text',''))) not between 1 and 300 or (item->>'required') is null or (item->>'blocking') is null then raise exception 'Valid checklist item required';end if;
   if nullif(item->>'area_id','') is not null and not exists(select 1 from public.areas where id=(item->>'area_id')::uuid and active) then raise exception 'Choose an active area';end if;
  end loop;
  if rid is null then
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   insert into public.pit_checklist_templates(name,description,kind,items,updated_by) values(trim(p->>'name'),coalesce(p->>'description',''),p->>'kind',p->'items',auth.uid()) returning id into rid;
  else
 -- BEGIN CURRENT AUTHORITY RECHECK
 perform 1 from public.pit_checklist_templates where id=rid for update;
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   update public.pit_checklist_templates set name=trim(p->>'name'),description=coalesce(p->>'description',''),kind=p->>'kind',items=p->'items',active=(p->>'active')::boolean,version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=rid and version=(p->>'version')::int;
   if not found then raise exception 'Template changed. Refresh before saving';end if;
  end if;return rid;
 elsif action='item' then
  select * into i from public.pit_checklist_run_items where id=rid for update;
  if not found or i.version is distinct from (p->>'version')::int or p->>'complete' is null then raise exception 'Checklist item changed. Refresh before saving';end if;
  select * into r from public.pit_checklist_runs where id=i.run_id;
  perform 1 from public.pit_events where id=r.event_id and status='active' for share;if not found then raise exception 'Event is no longer active';end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
  update public.pit_checklist_run_items set completed_by=case when (p->>'complete')::boolean then auth.uid() end,completed_at=case when (p->>'complete')::boolean then clock_timestamp() end,version=version+1 where id=rid;return rid;
 end if;
 if mid is not null then select * into m from public.pit_match_ops where id=mid for update;if not found then raise exception 'Match operations not found';end if;if eid is not null and eid<>m.event_id then raise exception 'Match belongs to a different event';end if;eid:=m.event_id;end if;
 perform 1 from public.pit_events where id=eid and status='active' for share;
 if not found then raise exception 'Select the active Pit event';end if;
 select * into c from public.pit_event_config where event_id=eid for update;
 if action='config' then
  if found then
   if c.version is distinct from (p->>'version')::int then raise exception 'Configuration changed. Refresh before saving';end if;
   if (c.tba_event_key is distinct from p->>'tba_event_key' or c.team_number is distinct from (p->>'team_number')::int) and exists(select 1 from public.pit_match_ops where event_id=eid and source='tba') then raise exception 'This event already has match operations. Use a new event for another event/team';end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   update public.pit_event_config set team_number=(p->>'team_number')::int,tba_event_key=p->>'tba_event_key',nexus_event_key=nullif(p->>'nexus_event_key',''),version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where event_id=eid;
  else
   if coalesce((p->>'version')::int,0)<>0 then raise exception 'Configuration changed';end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   insert into public.pit_event_config(event_id,team_number,tba_event_key,nexus_event_key,updated_by) values(eid,(p->>'team_number')::int,p->>'tba_event_key',nullif(p->>'nexus_event_key',''),auth.uid());
  end if;return eid;
 elsif action='manual_match' then
  if jsonb_typeof(p->'manual_label') is distinct from 'string' then raise exception 'Enter a practice label (1–80 characters)';end if;
  manual_name:=regexp_replace(p->>'manual_label','^\s+|\s+$','','g');
  if length(manual_name) not between 1 and 80 then raise exception 'Enter a practice label (1–80 characters)';end if;
  manual_time:=nullif(p->>'scheduled_at','')::timestamptz;
  if manual_time is not null and not isfinite(manual_time) then raise exception 'Enter a valid practice time';end if;
  if mid is null then
   if rid is null then raise exception 'A practice request ID is required';end if;
   manual_note:=coalesce(p->>'note','');
   -- The creation snapshot, rather than mutable current metadata, proves that a
   -- retry is the same actor/event/payload even after a later preparation edit.
   select * into m from public.pit_match_ops where id=rid for update;
   if found then
    select * into creation from public.pit_manual_match_events e where e.match_id=rid and e.action='created';
    if m.source<>'manual' or m.event_id<>eid or creation.performed_by is distinct from auth.uid()
      or creation.after_state->>'manual_label' is distinct from manual_name
      or (creation.after_state->>'scheduled_at')::timestamptz is distinct from manual_time
      or creation.after_state->>'note' is distinct from manual_note then raise exception 'Request ID already used';end if;
    return rid;
   end if;
   if exists(select 1 from public.pit_match_ops where event_id=eid and source='manual' and archived_at is null
     and lower(regexp_replace(manual_label,'\s+',' ','g'))=lower(regexp_replace(manual_name,'\s+',' ','g'))) then
    raise exception 'A practice with this label already exists in this event';
   end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   insert into public.pit_match_ops(id,event_id,match_key,source,manual_label,scheduled_at,note,updated_by)
     values(rid,eid,'manual:'||rid::text,'manual',manual_name,manual_time,manual_note,auth.uid()) returning to_jsonb(pit_match_ops) into after_match;
   insert into public.pit_manual_match_events(event_id,match_id,action,after_state,performed_by)
     values(eid,rid,'created',after_match,auth.uid());
   return rid;
  end if;
  if m.source<>'manual' then raise exception 'Select a manual practice match';end if;
  if m.archived_at is not null then raise exception 'Restore this practice before editing';end if;
  if m.version is distinct from (p->>'version')::int then raise exception 'Match operations changed. Refresh before saving';end if;
  if exists(select 1 from public.pit_match_ops where event_id=eid and source='manual' and archived_at is null and id<>mid
    and lower(regexp_replace(manual_label,'\s+',' ','g'))=lower(regexp_replace(manual_name,'\s+',' ','g'))) then
   raise exception 'A practice with this label already exists in this event';
  end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
  update public.pit_match_ops set manual_label=manual_name,scheduled_at=manual_time,
    version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=mid returning to_jsonb(pit_match_ops) into after_match;
  insert into public.pit_manual_match_events(event_id,match_id,action,before_state,after_state,performed_by)
    values(eid,mid,'metadata_updated',to_jsonb(m),after_match,auth.uid());
  return mid;
 elsif action in ('finish_manual_match','archive_manual_match') then
  if mid is null or m.source<>'manual' then raise exception 'Select a manual practice match';end if;
  if m.version is distinct from (p->>'version')::int then raise exception 'Match operations changed. Refresh before saving';end if;
  if action='finish_manual_match' then
   if m.archived_at is not null then raise exception 'Restore this practice before finishing';end if;
   if m.finished_at is not null then raise exception 'Practice already finished';end if;
   -- Finishing records only the local lifecycle. It does not invent a score,
   -- complete checklist work, or install/remove/cool the assigned battery.
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   update public.pit_match_ops set finished_at=clock_timestamp(),finished_by=auth.uid(),
     version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=mid returning to_jsonb(pit_match_ops) into after_match;
   manual_action:='finished';
  else
   if jsonb_typeof(p->'archived') is distinct from 'boolean' then raise exception 'Choose archive or restore';end if;
   archive_target:=(p->>'archived')::boolean;
   if archive_target=(m.archived_at is not null) then return mid;end if;
   if not archive_target and exists(select 1 from public.pit_match_ops where event_id=eid and source='manual' and archived_at is null and id<>mid
     and lower(regexp_replace(manual_label,'\s+',' ','g'))=lower(regexp_replace(m.manual_label,'\s+',' ','g'))) then
    raise exception 'A practice with this label already exists in this event';
   end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   update public.pit_match_ops set archived_at=case when archive_target then clock_timestamp() end,
     archived_by=case when archive_target then auth.uid() end,version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp()
     where id=mid returning to_jsonb(pit_match_ops) into after_match;
   manual_action:=case when archive_target then 'archived' else 'restored' end;
  end if;
  insert into public.pit_manual_match_events(event_id,match_id,action,before_state,after_state,performed_by)
    values(eid,mid,manual_action,to_jsonb(m),after_match,auth.uid());
  return mid;
 elsif action='match' then
  if (mid is null or m.source='tba') and c.event_id is null then raise exception 'Configure this event first';end if;
  if m.source='manual' and m.archived_at is not null then raise exception 'Restore this practice before editing';end if;
  if mid is null then
   if p->>'match_key' is null or p->>'match_key' !~ ('^'||c.tba_event_key||'_(qm[0-9]+|(ef|qf|sf|f)[0-9]+m[0-9]+)$') then raise exception 'Match key must belong to this event';end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
   insert into public.pit_match_ops(event_id,match_key,updated_by) values(eid,p->>'match_key',auth.uid()) on conflict(event_id,match_key) do nothing;
   select * into m from public.pit_match_ops where event_id=eid and match_key=p->>'match_key';return m.id;
  end if;
  if m.version is distinct from (p->>'version')::int then raise exception 'Match operations changed. Refresh before saving';end if;
  bid:=nullif(p->>'battery_id','')::uuid;
  if bid is not null and not exists(select 1 from public.pit_batteries where id=bid and active and status<>'RETIRED') then raise exception 'Choose an active battery';end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if pit_private.current_role() not in ('mentor') then
  perform 1 from public.team_member_positions mp join public.team_positions tp on tp.key=mp.position_key and tp.active
   where mp.user_id=auth.uid() and mp.revoked_at is null and tp.category in ('Program','Functional Leads','Other Leadership') for share of mp,tp;
 end if;
 if not pit_private.competition_manager() then raise exception 'Active competition leadership required' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
  update public.pit_match_ops set battery_id=bid,note=coalesce(p->>'note',''),version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=mid;
  if bid is distinct from m.battery_id then
   if m.battery_id is not null then insert into public.pit_battery_events(battery_id,event_id,event_type,match_number,notes,performed_by) values(m.battery_id,eid,'metadata_updated',case when m.source='manual' then 'Manual: '||m.manual_label else m.match_key end,'Match assignment removed',auth.uid());end if;
   if bid is not null then insert into public.pit_battery_events(battery_id,event_id,event_type,match_number,notes,performed_by) values(bid,eid,'metadata_updated',case when m.source='manual' then 'Manual: '||m.manual_label else m.match_key end,'Assigned to match; physical battery status unchanged',auth.uid());end if;
  end if;
  if m.source='manual' then
   select to_jsonb(o) into after_match from public.pit_match_ops o where o.id=mid;
   insert into public.pit_manual_match_events(event_id,match_id,action,before_state,after_state,performed_by)
     values(eid,mid,'preparation_updated',to_jsonb(m),after_match,auth.uid());
  end if;return mid;
 elsif action='run' then
  select * into t from public.pit_checklist_templates where id=(p->>'template_id')::uuid and active for share;
  if not found or t.version is distinct from (p->>'template_version')::int then raise exception 'Template changed or archived. Refresh';end if;
  if t.kind<>'general' and mid is null then raise exception 'Select match operations first';end if;
  select * into r from public.pit_checklist_runs where id=rid;
  if found then if r.started_by<>auth.uid() or r.template_id<>t.id or r.event_id<>eid or r.match_id is distinct from mid then raise exception 'Request ID already used';end if;return rid;end if;
  -- Retried starts above return their original snapshot. New runs respect the
  -- current lifecycle. Archived finished practices may still need inspection;
  -- existing items always remain completable while the Pit event is active.
  if m.source='manual' then
   if m.archived_at is not null and not (m.finished_at is not null and t.kind='post') then raise exception 'Practice is archived';end if;
   if t.kind='pre' and m.finished_at is not null then raise exception 'Practice is finished. Start a post-match inspection';end if;
   if t.kind='post' and m.finished_at is null then raise exception 'Finish this practice before starting a post-match inspection';end if;
  end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
  insert into public.pit_checklist_runs(id,event_id,match_id,template_id,template_version,name,kind,started_by) values(rid,eid,mid,t.id,t.version,t.name,t.kind,auth.uid());
  for item in select value from jsonb_array_elements(t.items) loop
   insert into public.pit_checklist_run_items(run_id,text,display_order,required,blocking,area_id) values(rid,trim(item->>'text'),idx,(item->>'required')::boolean,(item->>'blocking')::boolean,nullif(item->>'area_id','')::uuid);idx:=idx+1;
  end loop;return rid;
 elsif action in ('link_issue','report_issue') then
  if mid is null then raise exception 'Select a match';end if;
  if action='report_issue' then
   new_id:=public.pit_report_issue(p||jsonb_build_object('event_id',eid,'discovered_match',case when m.source='manual' then 'Manual: '||m.manual_label else m.match_key end));
  else
   perform pit_private.require_role(array['lead','admin_lead','mentor']);new_id:=(p->>'issue_id')::uuid;
  end if;
  select * into issue from public.pit_issues where id=new_id and event_id=eid for update;if not found then raise exception 'Issue belongs to a different event';end if;
  if exists(select 1 from public.pit_issue_matches where issue_id=new_id and match_id<>mid) then raise exception 'Issue already associated with another match';end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if action='link_issue' then perform pit_private.require_role(array['lead','admin_lead','mentor']);end if;
 -- END CURRENT AUTHORITY RECHECK
  insert into public.pit_issue_matches(issue_id,match_id,linked_by) values(new_id,mid,auth.uid()) on conflict(issue_id) do nothing;
  if found then insert into public.pit_issue_events(issue_id,performed_by,changes) values(new_id,auth.uid(),jsonb_build_object('competition_match',jsonb_build_object('from',null,'to',m.match_key)));end if;return new_id;
 else raise exception 'Unknown competition action';end if;
end $function$

CREATE OR REPLACE FUNCTION public.pit_report_issue(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_event uuid:=(p->>'event_id')::uuid; v_battery uuid:=nullif(p->>'battery_id','')::uuid;
begin
 perform pit_private.require_role(array['student','lead','admin_lead','mentor']);
 perform 1 from public.pit_events where id=v_event and status='active' for share;
 if not found then raise exception 'Select the active event before reporting an issue'; end if;
 if v_battery is not null and not exists(select 1 from public.pit_batteries where id=v_battery and active) then raise exception 'Battery is unavailable'; end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 -- END CURRENT AUTHORITY RECHECK
 insert into public.pit_issues(event_id,title,subsystem,severity,description,reported_by,discovered_match,battery_id)
 values(v_event,left(trim(p->>'description'),100),p->>'subsystem',p->>'severity',trim(p->>'description'),auth.uid(),coalesce(p->>'discovered_match',''),v_battery) returning id into v_id;
 insert into public.pit_issue_events(issue_id,performed_by,changes) values(v_id,auth.uid(),jsonb_build_object('status',jsonb_build_object('from',null,'to','OPEN')));
 if v_battery is not null then insert into public.pit_battery_events(battery_id,event_id,event_type,issue_id,performed_by) values(v_battery,v_event,'issue_linked',v_id,auth.uid()); end if;
 return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.pit_transition_battery(p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.pit_batteries; target text:=p->>'status'; v_event uuid:=nullif(p->>'event_id','')::uuid; v_voltage numeric:=nullif(p->>'voltage','')::numeric;
begin
 perform pit_private.require_role(array['student','lead','admin_lead','mentor']);
 -- Serialize installs so another device cannot silently replace the current battery.
 perform pg_advisory_xact_lock(4418,1);
 select * into b from public.pit_batteries where id=(p->>'id')::uuid for update;
 if not found then raise exception 'Battery not found'; end if;
 if b.status is distinct from p->>'expected_status' then raise exception 'Battery status changed. Refresh and try again.'; end if;
 if not b.active then raise exception 'Reactivate this battery before changing its status'; end if;
 if b.status='RETIRED' or target='RETIRED' then perform pit_private.require_role(array['mentor']); end if;
 if b.status='FLAGGED' and target<>'FLAGGED' then perform pit_private.require_role(array['lead','admin_lead','mentor']); end if;
 if target='ON ROBOT' and exists(select 1 from public.pit_batteries where status='ON ROBOT' and id<>b.id) then raise exception 'Remove the current battery before installing another.'; end if;
 if v_event is not null then
 perform 1 from public.pit_events where id=v_event and status='active' for share;
 if not found then raise exception 'Event changed. Refresh and try again.'; end if; end if;
 -- BEGIN CURRENT AUTHORITY RECHECK
 -- Recheck after blocking business locks; hold current actor authority through commit.
 perform 1 from public.profiles where id=auth.uid() and active and role::text=any(array['student','lead','admin_lead','mentor']) for share;
 if not found then raise exception 'Insufficient Pit Operations permissions' using errcode='42501';end if;
 if b.status='RETIRED' or target='RETIRED' then perform pit_private.require_role(array['mentor']);end if;
 if b.status='FLAGGED' and target<>'FLAGGED' then perform pit_private.require_role(array['lead','admin_lead','mentor']);end if;
 -- END CURRENT AUTHORITY RECHECK
 update public.pit_batteries set status=target,updated_at=clock_timestamp() where id=b.id;
 insert into public.pit_battery_events(battery_id,event_id,event_type,from_status,to_status,voltage,voltage_kind,match_number,notes,performed_by)
 values(b.id,v_event,case when target=b.status then 'measurement' else 'status_changed' end,b.status,target,v_voltage,case when v_voltage is null then null else p->>'voltage_kind' end,coalesce(p->>'match_number',''),coalesce(p->>'notes',''),auth.uid());
end $function$

CREATE OR REPLACE FUNCTION public.planning_save(entity text, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ident uuid:=coalesce(nullif(p->>'id','')::uuid,gen_random_uuid()); sid uuid; bid uuid; tid uuid;
 old jsonb; result jsonb; owners uuid[]; prior_owners uuid[]:=array[]::uuid[]; manager boolean; task_manager boolean; owner uuid; ar uuid; pred uuid; b public.planning_boards; t public.planning_tasks;
begin
 perform pg_advisory_xact_lock(4418,30);
 if not planning_private.member() then raise exception 'Active team account required' using errcode='42501';end if;
 -- Retained assignments never grant write access after a role demotion.
 -- Keep member() unchanged so active readonly accounts retain their read access.
 if not exists(select 1 from public.profiles where id=auth.uid() and active
  and role::text in ('student','lead','admin_lead','mentor')) then
  raise exception 'Active Planning writer account required' using errcode='42501';
 end if;
 manager:=planning_private.manager();
 task_manager:=manager or planning_private.project_lead();
 if entity not in ('season','group','board','item','task','step','comment') then raise exception 'Unknown Planning action';end if;
 if entity in ('season','group','board','item') and not manager then raise exception 'Planning leadership required' using errcode='42501';end if;
 if entity='season' then select to_jsonb(s) into old from public.planning_seasons s where id=ident;sid:=ident;
 elsif entity='group' then select to_jsonb(g) into old from public.planning_groups g where id=ident;sid:=coalesce((old->>'season_id')::uuid,(p->>'season_id')::uuid);
 elsif entity='item' then select to_jsonb(i) into old from public.planning_items i where id=ident;sid:=coalesce((old->>'season_id')::uuid,(p->>'season_id')::uuid);
 elsif entity='board' then select to_jsonb(x) into old from public.planning_boards x where id=ident;sid:=case when old is not null then (old->>'season_id')::uuid when p->>'kind'='area' then null else (p->>'season_id')::uuid end;
 elsif entity='task' then
  select * into t from public.planning_tasks where id=ident;old:=case when found then to_jsonb(t) end;
  bid:=coalesce(t.board_id,(p->>'board_id')::uuid);tid:=ident;
  select coalesce(array_agg(user_id order by user_id),array[]::uuid[]) into prior_owners from public.planning_task_assignees where task_id=ident;
  if old is not null then old:=old||jsonb_build_object('owner_ids',prior_owners,'owners',planning_private.task_owners(ident));end if;
  -- Fail closed for an old frontend; never interpret a legacy singleton as a replacement set.
  if p ? 'owner_id' then raise exception 'Task ownership has changed. Reload Planning before saving.';end if;
  if p ? 'owner_ids' then
   if jsonb_typeof(p->'owner_ids') is distinct from 'array' then raise exception 'Owners must be a list';end if;
   if exists(select 1 from jsonb_array_elements(p->'owner_ids') x where jsonb_typeof(x)<>'string') then raise exception 'Invalid owner identity';end if;
   select coalesce(array_agg(distinct x::uuid order by x::uuid),array[]::uuid[]) into owners from jsonb_array_elements_text(p->'owner_ids') x;
   if cardinality(owners)<>jsonb_array_length(p->'owner_ids') then raise exception 'Duplicate owner';end if;
  else owners:=prior_owners;end if;
 else
  if entity='step' then select to_jsonb(s) into old from public.planning_steps s where id=ident;end if;
  tid:=coalesce((old->>'task_id')::uuid,(p->>'task_id')::uuid);
  select * into t from public.planning_tasks where id=tid;bid:=t.board_id;
 end if;
 if old is not null and entity<>'comment' and (old->>'version')::integer is distinct from (p->>'version')::integer then raise exception 'Changed by another teammate. Refresh before saving.';end if;
 if entity in ('task','step','comment') then
  select * into b from public.planning_boards where id=bid;
  if not found or not b.active then raise exception 'Active board required';end if;sid:=b.season_id;
  if not task_manager and entity<>'comment' and (t.id is null or not exists(select 1 from public.planning_task_assignees a where a.task_id=t.id and a.user_id=auth.uid())) then raise exception 'Only assigned tasks may be updated' using errcode='42501';end if;
  if not task_manager and entity='task' and (owners is distinct from prior_owners or nullif(p->>'board_id','')::uuid is distinct from t.board_id or nullif(p->>'area_id','')::uuid is distinct from t.area_id) then raise exception 'Only leadership can reassign tasks' using errcode='42501';end if;
 end if;
 if entity<>'season' and sid is not null and not exists(select 1 from public.planning_seasons where id=sid and status<>'archived' and (manager or status='active')) then raise exception 'Season is unavailable or archived';end if;
 if entity='season' and old->>'status'='archived' then raise exception 'Archived seasons are read only';end if;
 if entity='task' and exists(select 1 from unnest(owners) u where not (u=any(prior_owners)) and not exists(select 1 from public.profiles where id=u and active)) then raise exception 'Choose an active owner';end if;
 owner:=nullif(p->>'owner_id','')::uuid;ar:=nullif(p->>'area_id','')::uuid;
 if owner is not null and not exists(select 1 from public.profiles where id=owner and active) then raise exception 'Choose an active owner';end if;
 if ar is not null and not exists(select 1 from public.areas where id=ar and active) then raise exception 'Choose an active area';end if;
 if entity='season' then
  insert into public.planning_seasons(id,name,start_date,end_date,status,created_by)
  values(ident,trim(p->>'name'),nullif(p->>'start_date','')::date,nullif(p->>'end_date','')::date,coalesce(p->>'status','draft'),auth.uid())
  on conflict(id) do update set name=excluded.name,start_date=excluded.start_date,end_date=excluded.end_date,status=excluded.status,updated_at=clock_timestamp(),version=planning_seasons.version+1 returning to_jsonb(planning_seasons.*) into result;
 elsif entity='group' then
  if coalesce((p->>'active')::boolean,true)=false and exists(select 1 from public.planning_items where group_id=ident) then raise exception 'Move plan items before archiving this group';end if;
  insert into public.planning_groups(id,season_id,name,display_order,active) values(ident,sid,trim(p->>'name'),coalesce((p->>'display_order')::integer,0),coalesce((p->>'active')::boolean,true))
  on conflict(id) do update set name=excluded.name,display_order=excluded.display_order,active=excluded.active,version=planning_groups.version+1 returning to_jsonb(planning_groups.*) into result;
 elsif entity='board' then
  if old is not null and (old->>'kind' is distinct from p->>'kind' or (old->>'season_id')::uuid is distinct from nullif(p->>'season_id','')::uuid) then raise exception 'Board type and season cannot change';end if;
  insert into public.planning_boards(id,season_id,name,description,kind,area_id,active,display_order,created_by)
  values(ident,sid,trim(p->>'name'),coalesce(p->>'description',''),p->>'kind',ar,coalesce((p->>'active')::boolean,true),coalesce((p->>'display_order')::integer,0),auth.uid())
  on conflict(id) do update set name=excluded.name,description=excluded.description,area_id=excluded.area_id,active=excluded.active,display_order=excluded.display_order,version=planning_boards.version+1 returning to_jsonb(planning_boards.*) into result;
 elsif entity='item' then
  pred:=nullif(p->>'predecessor_id','')::uuid;
  if pred is not null and exists(with recursive chain as (select id,predecessor_id from public.planning_items where id=pred union select i.id,i.predecessor_id from public.planning_items i join chain c on i.id=c.predecessor_id) select 1 from chain where id=ident) then raise exception 'Dependency would create a cycle';end if;
  if nullif(p->>'board_id','') is not null and not exists(select 1 from public.planning_boards where id=(p->>'board_id')::uuid and active and (season_id=sid or kind='area')) then raise exception 'Choose an active board in this season';end if;
  if nullif(p->>'group_id','') is not null and not exists(select 1 from public.planning_groups where id=(p->>'group_id')::uuid and season_id=sid and active) then raise exception 'Choose an active group';end if;
  insert into public.planning_items(id,season_id,title,description,kind,start_date,end_date,status,group_id,board_id,owner_id,area_id,predecessor_id,display_order)
  values(ident,sid,trim(p->>'title'),coalesce(p->>'description',''),p->>'kind',(p->>'start_date')::date,(p->>'end_date')::date,p->>'status',nullif(p->>'group_id','')::uuid,nullif(p->>'board_id','')::uuid,owner,ar,pred,coalesce((p->>'display_order')::integer,0))
  on conflict(id) do update set title=excluded.title,description=excluded.description,kind=excluded.kind,start_date=excluded.start_date,end_date=excluded.end_date,status=excluded.status,group_id=excluded.group_id,board_id=excluded.board_id,owner_id=excluded.owner_id,area_id=excluded.area_id,predecessor_id=excluded.predecessor_id,display_order=excluded.display_order,version=planning_items.version+1 returning to_jsonb(planning_items.*) into result;
 elsif entity='task' then
  insert into public.planning_tasks(id,board_id,title,description,status,priority,area_id,start_date,due_date,blocked_reason,created_by)
  values(ident,bid,trim(p->>'title'),coalesce(p->>'description',''),p->>'status',p->>'priority',ar,nullif(p->>'start_date','')::date,nullif(p->>'due_date','')::date,coalesce(p->>'blocked_reason',''),auth.uid())
  on conflict(id) do update set title=excluded.title,description=excluded.description,status=excluded.status,priority=excluded.priority,area_id=excluded.area_id,start_date=excluded.start_date,due_date=excluded.due_date,blocked_reason=excluded.blocked_reason,updated_at=clock_timestamp(),version=planning_tasks.version+1 returning to_jsonb(planning_tasks.*) into result;
  delete from public.planning_task_assignees where task_id=ident and not (user_id=any(owners));
  insert into public.planning_task_assignees(task_id,user_id,assigned_by)
   select ident,u,auth.uid() from unnest(owners) u where not (u=any(prior_owners));
  result:=result||jsonb_build_object('owner_ids',owners,'owners',planning_private.task_owners(ident));
 elsif entity='step' then
  insert into public.planning_steps(id,task_id,text,done,display_order) values(ident,tid,trim(p->>'text'),coalesce((p->>'done')::boolean,false),coalesce((p->>'display_order')::integer,0))
  on conflict(id) do update set text=excluded.text,done=excluded.done,display_order=excluded.display_order,version=planning_steps.version+1 returning to_jsonb(planning_steps.*) into result;
 else
  insert into public.planning_comments(id,task_id,text,author_id) values(ident,tid,trim(p->>'text'),auth.uid()) returning to_jsonb(planning_comments.*) into result;
 end if;
 insert into planning_private.history(entity,entity_id,task_id,actor_id,action,before_data,after_data)
 values(entity,ident,tid,auth.uid(),case when old is null then 'created' else 'updated' end,old,result);
 return ident;
end $function$

CREATE OR REPLACE FUNCTION public.sprint_review_save(action text, request_id uuid, expected_actor uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ident uuid; old jsonb; result jsonb; prior planning_review_private.requests; previous_version integer;
 r public.planning_sprint_reviews; u public.planning_sprint_review_updates; a public.planning_project_review_assignments;
 workflow jsonb; member_ids uuid[]; student_ids uuid[]; person_id uuid; task_id uuid; carried_id uuid; item jsonb; field text;
begin
 perform pg_advisory_xact_lock(4418,30);
 perform planning_review_private.actor(expected_actor);
 if request_id is null or p is null or jsonb_typeof(p)<>'object' or octet_length(p::text)>64000 then raise exception using errcode='SR422',message='Invalid request';end if;
 perform planning_review_private.authorize(action,p);
 select * into prior from planning_review_private.requests q where q.actor_id=expected_actor and q.request_id=sprint_review_save.request_id;
 if found then
  if prior.status='applied' and (prior.action is distinct from action or prior.payload is distinct from p) then raise exception using errcode='SR412',message='Request conflict';end if;
  return planning_review_private.receipt(request_id,expected_actor);
 end if;
 if action='review' then
  perform planning_review_private.keys(p,array['id','version','season_id','title','review_date','chair_id','agenda']);
  ident:=planning_review_private.uid(p->'id');select * into r from public.planning_sprint_reviews where id=ident;
  if r.id is not null then old:=to_jsonb(r);previous_version:=r.version;if r.season_id is distinct from planning_review_private.uid(p->'season_id') then raise exception using errcode='SR403',message='Stable season required';end if;end if;
 elsif action='assignment' then
  perform planning_review_private.keys(p,array['board_id','version','lead_id','supporter_ids']);
  ident:=planning_review_private.uid(p->'board_id');select * into a from public.planning_project_review_assignments where board_id=ident;
  if a.board_id is not null then old:=planning_review_private.assignment_json(ident);previous_version:=a.version;end if;
 else
  perform planning_review_private.keys(p-'decision_workflow',array['id','version','review_id','board_id','progress','blockers','evidence','tradeoffs','decisions_needed','decision_references','reported_decision','decision_rationale','reported_by_student_ids','next_test','linked_task_id','carry_from_update_id','unresolved']);
  ident:=planning_review_private.uid(p->'id');select * into u from public.planning_sprint_review_updates where id=ident;
  if u.id is not null then old:=to_jsonb(u);previous_version:=u.version;
   if u.review_id is distinct from planning_review_private.uid(p->'review_id') or u.board_id is distinct from planning_review_private.uid(p->'board_id') then raise exception using errcode='SR403',message='Stable update scope required';end if;
  elsif exists(select 1 from public.planning_sprint_review_updates x where x.review_id=planning_review_private.uid(p->'review_id') and x.board_id=planning_review_private.uid(p->'board_id')) then raise exception using errcode='SR409',message='Update already exists';end if;
 end if;
 if ident is null then raise exception using errcode='SR422',message='Identity required';end if;
 if previous_version is null then
  if p->'version' is distinct from 'null'::jsonb then raise exception using errcode='SR409',message='New version required';end if;
 elsif jsonb_typeof(p->'version') is distinct from 'number' or (p->>'version') !~'^[1-9][0-9]{0,9}$' or (p->>'version')::bigint is distinct from previous_version then raise exception using errcode='SR409',message='Stale version';end if;
 if action='review' then
  perform planning_review_private.text_field(p,'title',200,true);perform planning_review_private.text_field(p,'review_date',10,true);
  if (p->>'review_date')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or (p->>'review_date')::date not between date '0001-01-01' and date '9999-12-31' then raise exception using errcode='SR422',message='Finite calendar date required';end if;
  -- A date correction must preserve the order of existing carry-forward links.
  -- Otherwise later writes could create a cycle by first reversing meeting dates.
  if r.id is not null and exists(
   select 1 from public.planning_sprint_review_updates child
   join public.planning_sprint_review_updates source on source.id=child.carry_from_update_id
   join public.planning_sprint_reviews cr on cr.id=child.review_id
   join public.planning_sprint_reviews sr on sr.id=source.review_id
   where (cr.id=r.id or sr.id=r.id) and
   (case when sr.id=r.id then (p->>'review_date')::date else sr.review_date end,sr.created_at,sr.id)>=
   (case when cr.id=r.id then (p->>'review_date')::date else cr.review_date end,cr.created_at,cr.id)
  ) then raise exception using errcode='SR422',message='Keep carry-forward meeting order';end if;
  person_id:=planning_review_private.uid(p->'chair_id');
  if person_id is not null and not exists(select 1 from public.profiles x where x.id=person_id and x.active and x.role::text in ('student','lead','admin_lead','mentor')) and person_id is distinct from r.chair_id then raise exception using errcode='SR422',message='Choose an active chair';end if;
  if jsonb_typeof(p->'agenda') is distinct from 'array' or jsonb_array_length(p->'agenda')>30 then raise exception using errcode='SR422',message='Invalid agenda';end if;
  for item in select value from jsonb_array_elements(p->'agenda') loop
   perform planning_review_private.keys(item,array['title','presenter_id','duration_minutes']);perform planning_review_private.text_field(item,'title',200,true);
   if jsonb_typeof(item->'duration_minutes') is distinct from 'number' or (item->>'duration_minutes') !~'^[1-9][0-9]{0,2}$' or (item->>'duration_minutes')::integer>240 then raise exception using errcode='SR422',message='Invalid agenda duration';end if;
   person_id:=planning_review_private.uid(item->'presenter_id');
   if person_id is not null and not exists(select 1 from public.profiles x where x.id=person_id and x.active and x.role::text in ('student','lead','admin_lead','mentor'))
   and not exists(select 1 from jsonb_array_elements(coalesce(r.agenda,'[]')) x where x->>'presenter_id'=person_id::text) then raise exception using errcode='SR422',message='Choose an active presenter';end if;
  end loop;
  insert into public.planning_sprint_reviews(id,season_id,title,review_date,chair_id,agenda,recorded_by)
  values(ident,planning_review_private.uid(p->'season_id'),planning_review_private.clean(p->>'title'),(p->>'review_date')::date,planning_review_private.uid(p->'chair_id'),p->'agenda',auth.uid())
  on conflict(id) do update set title=excluded.title,review_date=excluded.review_date,chair_id=excluded.chair_id,agenda=excluded.agenda,version=planning_sprint_reviews.version+1,recorded_by=auth.uid(),recorded_at=clock_timestamp()
  returning to_jsonb(planning_sprint_reviews.*) into result;
 elsif action='assignment' then
  person_id:=planning_review_private.uid(p->'lead_id');member_ids:=planning_review_private.ids(p->'supporter_ids');
  if person_id is not null and not exists(select 1 from public.profiles x where x.id=person_id and x.active and x.role::text in ('student','lead','admin_lead')) and person_id is distinct from a.lead_id then raise exception using errcode='SR422',message='Choose an active student lead';end if;
  if person_id=any(member_ids) then raise exception using errcode='SR422',message='Lead already participates';end if;
  if exists(select 1 from unnest(member_ids) x where not exists(select 1 from public.profiles y where y.id=x and y.active and y.role::text in ('student','lead','admin_lead','mentor'))
   and not exists(select 1 from public.planning_project_review_supporters z where z.board_id=ident and z.user_id=x)) then raise exception using errcode='SR422',message='Choose active supporters';end if;
  insert into public.planning_project_review_assignments(board_id,lead_id,recorded_by) values(ident,person_id,auth.uid())
  on conflict(board_id) do update set lead_id=excluded.lead_id,version=planning_project_review_assignments.version+1,recorded_by=auth.uid(),recorded_at=clock_timestamp();
  delete from public.planning_project_review_supporters where board_id=ident and not(user_id=any(member_ids));
  insert into public.planning_project_review_supporters(board_id,user_id) select ident,x from unnest(member_ids) x on conflict do nothing;
  result:=planning_review_private.assignment_json(ident);
 else
  foreach field in array array['progress','blockers','tradeoffs','decisions_needed','reported_decision','decision_rationale','next_test'] loop perform planning_review_private.text_field(p,field,5000);end loop;
  perform planning_review_private.references_valid(p->'evidence');perform planning_review_private.references_valid(p->'decision_references');
  student_ids:=planning_review_private.ids(p->'reported_by_student_ids');
  if exists(select 1 from unnest(student_ids) x where not exists(select 1 from public.profiles y where y.id=x and y.active and y.role::text in ('student','lead','admin_lead')) and not(x=any(coalesce(u.reported_by_student_ids,'{}')))) then raise exception using errcode='SR422',message='Choose reported student participants';end if;
  -- Omitted field is a legacy client: preserve the existing workflow. JSON null explicitly clears it.
  workflow:=case when p ? 'decision_workflow' then nullif(p->'decision_workflow','null'::jsonb) else u.decision_workflow end;
  perform planning_review_private.decision_workflow_valid(workflow,u.decision_workflow,p);
  task_id:=planning_review_private.uid(p->'linked_task_id');carried_id:=planning_review_private.uid(p->'carry_from_update_id');
  select * into r from public.planning_sprint_reviews where id=planning_review_private.uid(p->'review_id');
  if task_id is not null and task_id is distinct from u.linked_task_id and not exists(select 1 from public.planning_tasks t join public.planning_boards b on b.id=t.board_id
   where t.id=task_id and b.active and (b.season_id=r.season_id or b.kind='area') and planning_review_private.board_visible(b.id)) then raise exception using errcode='SR422',message='Choose visible Planning work';end if;
  if carried_id is not null and not exists(select 1 from public.planning_sprint_review_updates x join public.planning_sprint_reviews y on y.id=x.review_id
   where x.id=carried_id and x.board_id=planning_review_private.uid(p->'board_id') and y.season_id=r.season_id and (y.review_date,y.created_at,y.id)<(r.review_date,r.created_at,r.id)) then raise exception using errcode='SR422',message='Choose an earlier update for this project';end if;
  if jsonb_typeof(p->'unresolved') is distinct from 'boolean' then raise exception using errcode='SR422',message='Invalid unresolved flag';end if;
  insert into public.planning_sprint_review_updates(id,review_id,board_id,progress,blockers,evidence,tradeoffs,decisions_needed,decision_references,reported_decision,decision_rationale,reported_by_student_ids,next_test,linked_task_id,carry_from_update_id,unresolved,decision_workflow,recorded_by)
  values(ident,r.id,planning_review_private.uid(p->'board_id'),p->>'progress',p->>'blockers',p->'evidence',p->>'tradeoffs',p->>'decisions_needed',p->'decision_references',p->>'reported_decision',p->>'decision_rationale',student_ids,p->>'next_test',task_id,carried_id,(p->>'unresolved')::boolean,workflow,auth.uid())
  on conflict(id) do update set progress=excluded.progress,blockers=excluded.blockers,evidence=excluded.evidence,tradeoffs=excluded.tradeoffs,decisions_needed=excluded.decisions_needed,decision_references=excluded.decision_references,reported_decision=excluded.reported_decision,decision_rationale=excluded.decision_rationale,reported_by_student_ids=excluded.reported_by_student_ids,next_test=excluded.next_test,linked_task_id=excluded.linked_task_id,carry_from_update_id=excluded.carry_from_update_id,unresolved=excluded.unresolved,decision_workflow=excluded.decision_workflow,version=planning_sprint_review_updates.version+1,recorded_by=auth.uid(),recorded_at=clock_timestamp()
  returning to_jsonb(planning_sprint_review_updates.*) into result;
 end if;
 insert into planning_review_private.history(action,entity_id,actor_id,request_id,before_data,after_data) values(action,ident,auth.uid(),request_id,old,result);
 insert into planning_review_private.requests(actor_id,request_id,action,payload,status,entity_id,version) values(auth.uid(),request_id,action,p,'applied',ident,(result->>'version')::integer);
 return planning_review_private.receipt(request_id,expected_actor);
exception when others then raise exception using errcode=case when sqlstate like 'SR%' then sqlstate else 'SR422' end,message=planning_review_private.error_message(case when sqlstate like 'SR%' then sqlstate else 'SR422' end),detail='',hint='';
end $function$

CREATE OR REPLACE FUNCTION public.team_manage(action text, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pr public.profiles; old_member public.team_attendance_members; assignment public.team_member_positions;
 reason text:=trim(coalesce(p->>'reason','')); target uuid:=(p->>'user_id')::uuid; next_area uuid:=nullif(p->>'primary_area_id','')::uuid; before_json jsonb;
begin
 -- Share Inventory's profile guard lock, preventing concurrent last-admin removal.
 perform pg_advisory_xact_lock(4418);
 if not team_private.admin() then raise exception 'Active Mentor required' using errcode='42501'; end if;
 if length(reason) not between 1 and 2000 then raise exception 'Explain the change (up to 2000 characters)'; end if;
 if action='create_area' then
 if length(trim(coalesce(p->>'name',''))) not between 1 and 100 or coalesce(p->>'slug','') !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'Area name and lowercase hyphenated key required'; end if;
 if length(p->>'slug')>100 then raise exception 'Area key is too long'; end if;
 insert into public.areas(name,slug) values(trim(p->>'name'),p->>'slug') returning id into next_area;
 insert into team_private.management_history(action,actor_id,reason,after_data) select action,auth.uid(),reason,jsonb_build_object('area_id',id,'name',name,'slug',slug) from public.areas where id=next_area;
 return;
 end if;
 select * into pr from public.profiles where id=target for update;
 if not found then raise exception 'Team member not found'; end if;
 if action='member' then
 if pr.updated_at is distinct from (p->>'expected_updated_at')::timestamptz then raise exception 'Member changed. Reload before saving.'; end if;
 if length(trim(coalesce(p->>'display_name',''))) not between 1 and 150 or coalesce(p->>'role','') not in ('student','lead','admin_lead','mentor','readonly') or p->>'active' is null then raise exception 'Valid name, role and active status required'; end if;
 if next_area is not null and not exists(select 1 from public.areas where id=next_area and active) then raise exception 'Choose an active area'; end if;
 if pr.active and pr.role::text in ('mentor') and (not (p->>'active')::boolean or p->>'role' not in ('mentor')) and not exists(select 1 from public.profiles where id<>target and active and role::text in ('mentor')) then raise exception 'Keep at least one active Mentor'; end if;
 if target=auth.uid() and p->>'role' is distinct from pr.role::text then raise exception 'Ask another mentor to change your account role' using errcode='42501'; end if;

 select * into old_member from public.team_attendance_members where student_id=target for update;
 if old_member.member_status is distinct from p->>'expected_member_status' or old_member.team_area is distinct from p->>'expected_team_area' then raise exception 'Registration changed. Reload before saving.'; end if;
 if p->>'member_status' is not null and p->>'member_status' not in ('prospective','registered','inactive') then raise exception 'Invalid member status'; end if;
 before_json:=jsonb_build_object('profile',to_jsonb(pr),'membership',to_jsonb(old_member));
 update public.profiles set display_name=trim(p->>'display_name'),role=p->>'role',active=(p->>'active')::boolean,primary_area_id=next_area,updated_at=clock_timestamp() where id=target;
 -- Keep the existing Attendance roster's area label compatible. Past snapshots are untouched.
 if p->>'member_status' is not null or old_member.student_id is not null then
 insert into public.team_attendance_members(student_id,member_status,team_area) values(target,coalesce(p->>'member_status',old_member.member_status),coalesce((select name from public.areas where id=next_area),''))
 on conflict(student_id) do update set member_status=excluded.member_status,team_area=excluded.team_area;
 end if;
 insert into team_private.management_history(user_id,action,actor_id,reason,before_data,after_data)
 select target,action,auth.uid(),reason,before_json,jsonb_build_object('profile',to_jsonb(n),'membership',(select to_jsonb(m) from public.team_attendance_members m where student_id=target)) from public.profiles n where id=target;
 elsif action='assign_position' then
 if not pr.active or pr.role::text not in ('student','lead','admin_lead','mentor') then raise exception 'Choose an active student or leadership account'; end if;
 if not exists(select 1 from public.team_positions where key=p->>'position_key' and active) then raise exception 'Choose an active position'; end if;
 insert into public.team_member_positions(user_id,position_key,assigned_by,assignment_reason) values(target,p->>'position_key',auth.uid(),reason) returning * into assignment;
 insert into team_private.management_history(user_id,action,actor_id,reason,after_data) values(target,action,auth.uid(),reason,to_jsonb(assignment));
 elsif action='revoke_position' then
 select * into assignment from public.team_member_positions where id=(p->>'assignment_id')::uuid and user_id=target and revoked_at is null for update;
 if not found then raise exception 'Active assignment not found. Reload.'; end if;
 update public.team_member_positions set revoked_by=auth.uid(),revoked_at=clock_timestamp(),revoke_reason=reason where id=assignment.id;
 insert into team_private.management_history(user_id,action,actor_id,reason,before_data,after_data) select target,action,auth.uid(),reason,to_jsonb(assignment),to_jsonb(n) from public.team_member_positions n where id=assignment.id;
 else raise exception 'Unknown team management action'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.team_operations_manage(p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pr public.profiles; membership public.team_attendance_members; before_json jsonb; target uuid; reason text;
begin
 perform pg_advisory_xact_lock(4418);
 perform 1 from public.profiles where id=auth.uid() and active and role::text='admin_lead' for share;
 if not found then raise exception 'Active Admin Lead required' using errcode='42501';end if;
 if p is null or jsonb_typeof(p)<>'object' then raise exception 'Member details are required';end if;
 if exists(select 1 from jsonb_object_keys(p) k where k not in ('user_id','display_name','member_status','expected_updated_at','expected_member_status','expected_team_area','reason'))
 or not (p ?& array['user_id','display_name','member_status','expected_updated_at','expected_member_status','expected_team_area','reason']) then raise exception 'Only display name and Attendance registration may be changed';end if;
 target:=(p->>'user_id')::uuid;reason:=trim(coalesce(p->>'reason',''));
 if target is null or length(trim(coalesce(p->>'display_name',''))) not between 1 and 150 or length(reason) not between 1 and 2000 then raise exception 'A member, valid display name and reason are required';end if;
 if p->>'member_status' is not null and p->>'member_status' not in ('prospective','registered','inactive') then raise exception 'Choose a valid registration status';end if;
 select * into pr from public.profiles where id=target for update;
 if not found or pr.role::text not in ('readonly','student','lead','admin_lead') then raise exception 'Ordinary student account required' using errcode='42501';end if;
 if pr.updated_at is distinct from (p->>'expected_updated_at')::timestamptz then raise exception 'Member changed. Refresh before saving.';end if;
 select * into membership from public.team_attendance_members where student_id=target for update;
 if membership.member_status is distinct from p->>'expected_member_status' or membership.team_area is distinct from p->>'expected_team_area' then raise exception 'Registration changed. Refresh before saving.';end if;
 if membership.student_id is not null and p->>'member_status' is null then raise exception 'Choose a valid registration status';end if;
 before_json:=jsonb_build_object('profile',to_jsonb(pr),'membership',to_jsonb(membership));
 update public.profiles set display_name=trim(p->>'display_name'),updated_at=clock_timestamp() where id=target;
 if p->>'member_status' is not null then
  insert into public.team_attendance_members(student_id,member_status,team_area) values(target,p->>'member_status',coalesce((select name from public.areas where id=pr.primary_area_id),''))
  on conflict(student_id) do update set member_status=excluded.member_status,team_area=excluded.team_area;
 end if;
 insert into team_private.management_history(user_id,action,actor_id,reason,before_data,after_data)
 select target,'member_details',auth.uid(),reason,before_json,jsonb_build_object('profile',to_jsonb(n),'membership',(select to_jsonb(m) from public.team_attendance_members m where student_id=target)) from public.profiles n where id=target;
end $function$

CREATE OR REPLACE FUNCTION public.verify_balance_location(p_location uuid, p_expected jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;expected_count integer;
begin
 if not private.can_count() then raise exception 'No audit permission' using errcode='42501';end if;
 if not exists(select 1 from public.locations where id=p_location and active) then raise exception 'Location is archived';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_location::text,4418));
 perform 1 from public.inventory_items where location_id=p_location or id in(select inventory_item_id from public.inventory_balances where location_id=p_location and quantity>0) order by id for update;
 -- Re-read committed authority after the item-lock wait; do not reuse a pre-wait helper result.
 if not exists(select 1 from public.profiles where id=auth.uid() and active and role::text in ('student','lead','admin_lead','mentor')) then
  raise exception 'You do not have permission to change inventory' using errcode='42501';
 end if;
 select count(*) into expected_count from public.inventory_items where location_id=p_location or id in(select inventory_item_id from public.inventory_balances where location_id=p_location and quantity>0);
 if expected_count<>jsonb_array_length(p_expected) then raise exception 'Location contents changed. Review again.';end if;
 for r in select * from public.inventory_items where location_id=p_location or id in(select inventory_item_id from public.inventory_balances where location_id=p_location and quantity>0) loop
  if not exists(select 1 from jsonb_array_elements(p_expected) e where e->>'id'=r.id::text and (e->>'updated_at')::timestamptz=r.updated_at) then raise exception 'Location contents changed. Review again.';end if;
  insert into public.inventory_balances(inventory_item_id,location_id,quantity) values(r.id,p_location,0) on conflict do nothing;
  update public.inventory_balances set last_verified_at=clock_timestamp(),last_verified_by=auth.uid(),updated_at=clock_timestamp() where inventory_item_id=r.id and location_id=p_location;
  perform set_config('app.balance_sync','yes',true);
  perform set_config('app.drawer_audit','yes',true);
  update public.inventory_items set last_verified_at=case when location_id=p_location then clock_timestamp() else last_verified_at end where id=r.id;
  perform set_config('app.drawer_audit','',true);
  perform set_config('app.balance_sync','',true);
  if r.location_id is distinct from p_location then insert into public.inventory_events(inventory_item_id,item_name,area_id,user_id,event_type,notes) values(r.id,r.name,r.area_id,auth.uid(),'drawer_verified',p_location::text);end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.team_manage_v2(action text, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pos public.team_positions; ar public.areas; pr public.profiles; reason text:=trim(coalesce(p->>'reason','')); before_json jsonb;
begin
 perform pg_advisory_xact_lock(4418);
 if not team_private.admin() then raise exception 'Active Mentor required' using errcode='42501';end if;
 if length(reason) not between 1 and 2000 then raise exception 'Explain the change (up to 2000 characters)';end if;
 if action in ('member','assign_position','revoke_position','create_area') then
  perform public.team_manage(action,p);return;
 elsif action='member_state' then
  select * into pr from public.profiles where id=(p->>'user_id')::uuid for update;
  if not found or pr.updated_at is distinct from (p->>'expected_updated_at')::timestamptz then raise exception 'Member changed. Reload before saving.';end if;
  if p->>'active' is null then raise exception 'Active state required';end if;
  if pr.active and pr.role::text in ('mentor') and not (p->>'active')::boolean and not exists(select 1 from public.profiles where id<>pr.id and active and role::text in ('mentor')) then raise exception 'Keep at least one active Mentor';end if;
  update public.profiles set active=(p->>'active')::boolean,updated_at=clock_timestamp() where id=pr.id;
  insert into team_private.management_history(user_id,action,actor_id,reason,before_data,after_data)
  select pr.id,case when n.active then 'member_reactivated' else 'member_deactivated' end,auth.uid(),reason,to_jsonb(pr),to_jsonb(n) from public.profiles n where n.id=pr.id;
 elsif action='position_save' then
  if coalesce((p->>'create')::boolean,false) then
   insert into public.team_positions(key,name,description,category,display_order,active) values(p->>'key',trim(p->>'name'),coalesce(p->>'description',''),p->>'category',(p->>'display_order')::integer,true) returning * into pos;
  else
   select * into pos from public.team_positions where key=p->>'key' for update;
   if not found or pos.version is distinct from (p->>'version')::integer then raise exception 'Position changed. Reload before saving.';end if;
   before_json:=to_jsonb(pos);
   update public.team_positions set name=trim(p->>'name'),description=coalesce(p->>'description',''),category=p->>'category',display_order=(p->>'display_order')::integer,active=(p->>'active')::boolean,version=version+1 where key=pos.key returning * into pos;
  end if;
  insert into team_private.management_history(action,actor_id,reason,before_data,after_data) values(case when before_json is null then 'position_created' else 'position_updated' end,auth.uid(),reason,before_json,to_jsonb(pos));
 elsif action='area_save' then
  select * into ar from public.areas where id=(p->>'id')::uuid for update;
  if not found or ar.name is distinct from p->>'expected_name' or ar.active is distinct from (p->>'expected_active')::boolean then raise exception 'Area changed. Reload before saving.';end if;
  if length(trim(coalesce(p->>'name',''))) not between 1 and 100 or p->>'active' is null then raise exception 'Area name and active state required';end if;
  -- Stable IDs/slugs and historical snapshots stay intact. Sync only current roster labels whose profile ID links to this area.
  update public.areas set name=trim(p->>'name'),active=(p->>'active')::boolean where id=ar.id;
  if ar.name<>trim(p->>'name') then update public.team_attendance_members m set team_area=trim(p->>'name') from public.profiles roster_profile where roster_profile.id=m.student_id and roster_profile.primary_area_id=ar.id and m.team_area=ar.name;end if;
  insert into team_private.management_history(action,actor_id,reason,before_data,after_data)
  select case when ar.active and not n.active then 'area_archived' when not ar.active and n.active then 'area_reactivated' else 'area_renamed' end,auth.uid(),reason,to_jsonb(ar),to_jsonb(n) from public.areas n where n.id=ar.id;
 else raise exception 'Unsupported action. Deletion and area merging are not available.';end if;
end $function$
